// Üretilen dosya: tool/ozgun/uret.py. Tarih · Amerika ve Afrika tarihi: yerli uygarlıklar, sömürgecilik, bağımsızlıklar (orta).
const ozHistory12Orta = <(String, String, List<String>, String)>[
  ('Maya yazısının çözümlenmesi sırasında glifler üzerinde yapılan incelemeler bu yazının nasıl işlediğini göstermiştir. Aşağıdakilerden hangisi doğrudur?', 'Hem sözcük hem hece simgelerini birlikte kullanan bir yazıdır.', ['Yalnızca ses birimlerini gösteren bir alfabedir.', 'Yalnızca sayıları kaydeden bir kayıt sistemidir.', 'Sadece resimlerden oluşan, okunuşu olmayan bir yazıdır.'], 'Maya glifleri hem bir sözcüğü bütünüyle hem de hece değerlerini gösterir; bu karma yapı çözümlemeyi uzun süre zorlaştırmıştır.'),
  ('Mayaların 365 günlük güneş takvimi (Haab) 18 aya bölünmüştü. Her ay 20 gün sürüyorsa yılı tamamlamak için ayrıca kaç günlük bir dönem gerekir?', '5 günlük uğursuz sayılan ek dönem', ['3 günlük dönem', '7 günlük dönem', 'Dört yılda bir eklenen artık gün dönemi'], '18 x 20 = 360 gün eder; kalan 5 gün Wayeb adlı, uğursuz sayılan günlerdi.'),
  ('Klasik dönem Maya dünyasının siyasi yapısı hakkında aşağıdakilerden hangisi söylenebilir?', 'Tek bir merkezden yönetilmeyen, birbiriyle savaşıp ittifak kuran şehir devletlerinden oluşuyordu.', ['Başkenti Tikal olan merkezî bir imparatorluktu.', 'Bütün kentler tek bir rahip meclisince yönetilirdi.', 'Köylerin seçtiği temsilcilerden oluşan bir federasyondu.'], 'Mayalar hiçbir zaman Aztekler gibi birleşik bir imparatorluk kurmadı; her kentin kendi hükümdarı vardı.'),
  ('Yucatán\'daki Chichén Itzá\'da bulunan El Castillo piramidinde ilkbahar ve sonbahar ekinokslarında merdivende yılan biçimli bir gölge oluşur. Bu durum en çok neyin kanıtıdır?', 'Mayaların astronomi bilgisini mimariyle birleştirmesinin', ['Piramidin Aztekler tarafından inşa edildiğinin', 'Yılın dört mevsimli olmadığının', 'Mayaların demir alet kullandığının'], 'Tapınak, Kukulkan (tüylü yılan) kültüyle gök olaylarını ilişkilendirecek biçimde tasarlanmıştır; gölge hareketi bunu gösterir.'),
  ('Mezoamerika\'da kakao çekirdeklerinin bir takas aracı olarak kullanılması hangi sonucu doğurmuştur?', 'Madenî para yokken ticarette standart bir değer ölçüsünün oluşması', ['Kakaonun yalnızca soylulara yasaklanması', 'Gümüş madenlerinin kapatılması', 'Krallıklar arasında ticaretin tamamen durması'], 'Kakao taşınabilir, sayılabilir ve değerliydi; Aztek pazarlarında küçük alışverişlerde para gibi işlev gördü.'),
  ('Klasik Maya güney ova kentlerinin 9. yüzyıldan itibaren terk edilmesini açıklamak için öne sürülen başlıca etkenler hangileridir?', 'Tekrarlayan kuraklıklar ve kentler arası savaşlar', ['Avrupalıların getirdiği salgınlar', 'Aztek ordusunun işgali', 'Büyük bir deniz seviyesi yükselmesi'], 'Çöküş Avrupalılardan yüzyıllar önce yaşandı; göl çökeltilerindeki kuraklık izleri ve artan savaşlar temel açıklamalar arasındadır.'),
  ('"Maya uygarlığı tamamen yok oldu" görüşü neden yanlıştır?', 'Maya dillerini konuşan milyonlarca insan bugün Guatemala ve Meksika\'da yaşıyor.', ['Maya kentleri bugün de başkent olarak kullanılıyor.', 'Maya yazısı hâlâ resmî yazı olarak kullanılıyor.', 'Maya hükümdarları günümüzde de yönetimdedir.'], 'Klasik dönemin kentleri terk edilmiş olsa da Maya halkı ve dilleri sürmektedir; çöküş siyasi merkezlerin yıkılması anlamına gelir.'),
  ('1428 dolaylarında Tenochtitlan, Texcoco ve Tlacopan arasında kurulan ittifak Aztek yayılmasında nasıl bir rol oynamıştır?', 'Ortak seferlerle komşu halkları haraca bağlayan askerî-siyasi bir birlik sağlamıştır.', ['Üç kenti yalnızca ticari olarak birleştirmiştir.', 'Maya kentlerine karşı savunma paktı olmuştur.', 'Rahip sınıfını yönetimden uzaklaştırmıştır.'], 'Üçlü İttifak, fethedilen toprakların ganimet ve haraçlarının paylaşıldığı bir yapıydı; Tenochtitlan zamanla ittifakın baskın gücü oldu.'),
  ('Aztek imparatorluğuna bağlanan halklar yönetime ne tür bir yükümlülük getirdiği için hoşnutsuzluk duyuyordu?', 'Düzenli haraç ve kurban için esir göndermek', ['Askerî eğitim için topraklarını bırakmak', 'Dillerini unutmak zorunda kalmak', 'Yeni bir tanrıya inanmak zorunda kalmak'], 'Aztekler fethedilen halkların iç yönetimine çoğunlukla karışmaz, buna karşılık ağır haraç alırdı; bu nedenle birçok halk İspanyollara yöneldi.'),
  ('Cortés\'in 1519\'da Veracruz kıyısına çıktıktan sonra gemilerini kullanılmaz hale getirmesi, ekibi açısından ne anlama geliyordu?', 'Geri dönüş yolunun kapanması ve ilerlemekten başka seçenek kalmaması', ['Yeni gemilerin satın alınması', 'Aztek barış teklifinin kabulü', 'Kralın emrinin yerine getirilmesi'], 'Kıyıdaki geri çekilme olasılığını ortadan kaldırmak, askerlerin kararlılığını artırmayı ve Küba valisinin emrine karşı gelmeyi amaçlıyordu.'),
  ('1520\'de Tenochtitlan\'da yayılan çiçek hastalığı Aztek yönetimini nasıl etkilemiştir?', 'Nüfusu azaltmış ve hükümdar Cuitláhuac\'ın da ölümüne yol açmıştır.', ['Yalnızca İspanyol askerlerini etkilemiştir.', 'Aztek ordusunu kuvvetlendirmiştir.', 'Kentin su kaynaklarını kurutmuştur.'], 'Bağışıklığı bulunmayan yerli halk çiçek hastalığından kırıldı; Moctezuma\'dan sonra gelen Cuitláhuac da kısa sürede öldü.'),
  ('Aztek inancında güneşin her gün yoluna devam etmesi için kurban sunulması gerektiği düşüncesi toplumda hangi sonucu doğurmuştur?', 'Esir sağlama amaçlı savaşların ve kurban törenlerinin önem kazanması', ['Askerliğin tamamen kaldırılması', 'Tarım yapılmasının yasaklanması', 'Ticaretin durması'], 'Güneşi \'beslemek\' için kurban gerektiğine inanılması, \'çiçek savaşları\' gibi esir almayı amaçlayan çatışmaları besledi.'),
  ('Cortés\'in Aztek karşıtı müttefikleri sayesinde 1521\'de Tenochtitlan\'ı almasını açıklayan en isabetli yargı hangisidir?', 'Teknolojik üstünlüğe, yerli müttefiklere ve salgına birlikte dayanan bir başarı olmuştur.', ['Yalnızca atlar ve ateşli silahlar yüzünden kazanılmıştır.', 'Aztek ordusunun hiç savaşmaması sonucudur.', 'Mayaların yardımı sayesinde olmuştur.'], 'Fetih tek nedenle açıklanamaz: çelik silahlar ve atlar, binlerce yerli savaşçı ve çiçek salgını bir araya gelmiştir.'),
  ('İnka İmparatorluğu\'nda hükümdar hangi unsurla anılırdı ve nasıl kutsal sayılırdı?', 'Sapa İnka; güneş tanrısı İnti\'nin oğlu sayılırdı.', ['Tlatoani; tüylü yılanın temsilcisi sayılırdı.', 'Firavun; Nil\'in tanrısı sayılırdı.', 'Kaan; gök tanrının elçisi sayılırdı.'], 'Sapa İnka \'biricik İnka\' demektir; hükümdarın Güneş soyundan geldiğine inanılır, bu inanç yönetimini meşrulaştırırdı.'),
  ('İnka yönetiminin fethettiği halklara Quechua dilini yaymasının temel amacı neydi?', 'Çok dilli imparatorlukta idari iletişimi kolaylaştırmak', ['Halkı Hristiyanlığa geçirmek', 'Ticarette kullanılan bir alfabe yaymak', 'Yerli dilleri tamamen yasaklamak'], 'Quechua, devlet görevlileri ve askerler aracılığıyla bölgeler arasında ortak dil işlevi gördü; bugün de milyonlarca kişi bu dili konuşur.'),
  ('İnka hükümdarı Huayna Capac\'ın ölümünden sonra İnka tahtı için Huáscar ile Atahualpa arasında yaşanan çekişmenin imparatorluk üzerindeki etkisi ne olmuştur?', 'Savaş ve çiçek salgınıyla devleti zayıflatıp İspanyol ilerleyişini kolaylaştırmıştır.', ['Yeni bir hanedanın kurulmasını sağlamıştır.', 'Aztek ittifakının güçlenmesine yol açmıştır.', 'Güney Amerika\'da bağımsız şehir devletleri doğurmuştur.'], 'Pizarro\'nun gelişinden hemen önce iç savaş sona ermiş, Atahualpa\'nın ordusu yorgun ve devlet bölünmüş hâldeydi.'),
  ('Atahualpa\'nın 1532\'de Cajamarca\'da tutsak edilmesinden sonra İspanyollar ondan hangi karşılığı almıştır?', 'Bir odayı altın ve iki kez gümüşle doldurma sözü', ['Cuzco\'nun anahtarı', 'Büyük bir tarım arazisi', 'Hristiyan olma yemini'], 'Atahualpa, serbest kalmak için fidye olarak dolu bir odayı altınla doldurmayı kabul etti; ödemeye rağmen 1533\'te idam edildi.'),
  ('1780\'de Peru\'da yerli halkın ağır vergilere ve mit\'a uygulamasına karşı çıkardığı büyük isyanın önderi kimdir?', 'II. Túpac Amaru', ['Simón Bolívar', 'Miguel Hidalgo', 'Francisco de Miranda'], 'José Gabriel Condorcanqui, İnka soyundan geldiğini öne sürerek Túpac Amaru adını aldı; isyan bastırıldı fakat sömürge karşıtı bilinci güçlendirdi.'),
  ('İnka duvarlarının harç kullanılmadan, taşlar birbirine tam oturacak biçimde örülmesinin sağladığı avantaj aşağıdakilerden hangisidir?', 'Depreme dayanıklılık', ['Taşların su geçirmemesi', 'Duvarların renkli görünmesi', 'Rüzgârın içeri girmesi'], 'Esnek bağlantılar sayesinde sarsıntıda taşlar yer değiştirse bile yeniden yerine otururdu; And bölgesi deprem kuşağında yer alır.'),
  ('Moche (MS 1-8. yüzyıl) toplumunun Peru kıyısında bıraktığı eserlerde dikkat çeken özellik hangisidir?', 'Gerçekçi portre çömlekler ve altın-gümüş süs eşyaları', ['Çivi yazılı tabletler', 'Demir savaş araçları', 'Mermer tapınak heykelleri'], 'Moche seramikleri insan yüzlerini ve günlük yaşamı canlı betimler; Sipán gibi mezarlardan zengin altın eserler çıkmıştır.'),
  ('Mezoamerika ile And uygarlıklarını yazı ve kayıt sistemleri bakımından karşılaştıran bir öğrenci hangi sonuca varır?', 'Mayalar glif yazısı, İnkalar ise düğümlü iplerle kayıt kullanmıştır.', ['İkisi de alfabe kullanmıştır.', 'İkisi de hiçbir kayıt sistemi kullanmamıştır.', 'Yalnız İnkalar yazı kullanmıştır.'], 'Maya yazısı sözcük ve hece simgelerine dayanırken İnkalar yazıyı tanımadan quipu ile idari veri tutmuştur; kayıt biçimleri farklıdır.'),
  ('Güney Amerika\'nın Potosí kentinde 1545\'te bulunan büyük gümüş yataklarının dünya ekonomisine etkisi aşağıdakilerden hangisidir?', 'İspanya aracılığıyla Avrupa ve Asya\'ya akan gümüş fiyat artışlarına yol açmıştır.', ['Altın fiyatlarının düşmesine neden olmuştur.', 'Yerli halkın zenginleşmesini sağlamıştır.', 'Avrupa\'da gümüş değerinin yükselmesini sağlamıştır.'], 'Potosí gümüşü İspanya\'ya, oradan da Avrupa ve Çin ticaretine girdi; bolluk nedeniyle fiyatlar yükseldi ve gümüşün değeri düştü.'),
  ('Kuzeydoğu Amerika\'da Mohawk, Oneida, Onondaga, Cayuga ve Seneca halklarının oluşturduğu, ortak konseyle karar alan siyasi birliğe ne ad verilir?', 'İrokua (Haudenosaunee) Konfederasyonu', ['Powhatan Konfederasyonu', 'Pueblo Birliği', 'Muskogee (Creek) Konfederasyonu ve müttefikleri'], 'Beş ulus, Büyük Barış Yasası\'na dayanan bir konsey düzeniyle ortak kararlar alırdı; 1722\'de Tuscarora da katılınca birlik altı ulusa çıktı.'),
  ('Doğu Kuzey Amerika yerli çiftçiliğinde birlikte ekilen mısır, fasulye ve kabağa \'Üç Kız Kardeş\' denmesinin başlıca nedeni nedir?', 'Bitkilerin birbirinin gelişimini desteklemesi ve dengeli beslenme sağlaması', ['Üçünün de aynı mevsimde hasat edilmesi', 'Üçünün de yalnızca dinî törenlerde kullanılması', 'Üçünün de ihracat için yetiştirilmesi'], 'Fasulye toprağa azot verir, mısır fasulyeye destek olur, kabak yaprakları toprağı örter; üçü birlikte hem verim hem beslenme dengesi sağlar.'),
  ('Cherokee ulusundan Sequoyah\'ın 1820\'lerde geliştirdiği yazı sistemi hangi türdendir?', 'Her heceye ayrı bir simge veren hece yazısı', ['Hiyeroglif', 'Çivi yazısı', 'Latin alfabesinin kopyası'], 'Sequoyah\'ın 85 kadar simgeden oluşan hece yazısı birkaç yıl içinde yaygınlaştı; Cherokee halkı kısa sürede yüksek okuryazarlığa ulaştı.'),
  ('Büyük Ovalar\'da bizon avcılığına dayalı göçebe yaşam, hangi etkenle köklü biçimde dönüşmüştür?', 'İspanyollarla gelen atların yerli halklar arasında yayılması', ['Demiryolunun yerlilerce yapılması', 'Buğday tarımına geçilmesi', 'Vikinglerin getirdiği demir silahlar'], 'Atlar bizon avını hızlandırdı, taşınmayı kolaylaştırdı ve Sioux, Comanche gibi toplulukları güçlü atlı kültürlere dönüştürdü.'),
  ('1763\'te İngiltere Kralı\'nın yayımladığı bildiri ile Appalachian Dağları\'nın batısına yerleşme neden yasaklandı?', 'Yerlilerle yeni çatışmaları önlemek ve sömürge sınırını denetlemek', ['Kolonistlerin vergiden kaçmasını önlemek', 'Fransız yerleşimcileri korumak', 'Madenleri devlet mülkiyetine almak'], 'Pontiac İsyanı\'nın ardından Londra, yerli saldırılarından ve yeni savaş maliyetlerinden kaçınmak istedi; bu karar kolonistleri rahatsız etti.'),
  ('Shawnee lideri Tecumseh\'in 1810 dolayında amaçladığı şey aşağıdakilerden hangisidir?', 'Yerli halkların toprakları satmasını önleyen bir birlik kurmak', ['İngiliz Kraliyetine bağlanmayı reddetmek', 'ABD vatandaşlığı almak', 'Buğday ticaretini geliştirmek'], 'Tecumseh, toprakların bütün yerlilerin ortak malı olduğunu savunup kabileleri birleştirmeye çalıştı; 1812 Savaşı\'nda İngilizlerin yanında dövüştü.'),
  ('1830\'da Başkan Andrew Jackson döneminde çıkarılan Kızılderili Göç Yasası\'nın sonucu olarak güneydoğu halkları hangi bölgeye sürülmüştür?', 'Mississippi\'nin batısındaki \'Kızılderili Bölgesi\'ne', ['Alaska\'ya', 'Meksika sınırına', 'Büyük Göller çevresine'], 'Yasa, Cherokee, Creek, Choctaw, Chickasaw ve Seminole halklarının toprak ve haklarını gasp ederek Oklahoma bölgesine zorla göçüne dayanak oldu.'),
  ('1876\'da Little Bighorn\'da General Custer\'in 7. Süvari Alayı\'nı yenilgiye uğratan topluluklar hangileridir?', 'Lakota Sioux ve Kuzey Cheyenne savaşçıları', ['Apaçiler ve Navajolar', 'Seminoleler ve Creekler', 'İrokualar ve Mohawklar'], 'Sitting Bull ve Crazy Horse gibi liderlerin çevresinde toplanan birlikler Custer\'in birliğini yok etti; ancak bu zafer ordunun sert karşılığını tetikledi.'),
  ('1887 tarihli Dawes Yasası\'nın kabilelerin ortak topraklarını bireysel parsellere bölmesi hangi sonucu doğurmuştur?', 'Yerlilerin elindeki toprak miktarının büyük ölçüde azalması', ['Kabile yönetimlerinin güçlenmesi', 'Yerli topraklarının iki katına çıkması', 'Yerlilere ücretsiz üniversite hakkı verilmesi'], 'Parselleme sonrasında artan topraklar beyaz yerleşimcilere satıldı; yerlilerin toprakları birkaç on yılda milyonlarca hektar azaldı.'),
  ('Carlisle Indian Industrial School gibi yatılı okulların temel amacı neydi?', 'Yerli çocukları kendi kültür ve dillerinden koparıp asimile etmek', ['Yerli dillerini yaygınlaştırmak', 'Çocuklara geleneksel avcılığı öğretmek', 'Kabile konseyleri için memur yetiştirmek'], '1879\'da kurulan bu okullarda çocuklara yerli dil ve giysi yasaklandı; kurucunun sloganı \'Kızılderiliyi öldür, insanı kurtar\' idi.'),
  ('1870\'lerde ve 1880\'lerde Büyük Ovalar\'da bizon sürülerinin yok edilmesinin yerli halklar üzerindeki en önemli etkisi neydi?', 'Geçim kaynaklarını kaybederek rezervlere bağımlı hâle gelmeleri', ['Yeni demir silahlar kazanmaları', 'Batıya göç etmeleri', 'Tarıma geçerek zenginleşmeleri'], 'Ovalardaki halklar yiyecek, barınak ve giyeceği bizondan sağlıyordu; bizonların azalması direnişi zayıflattı ve rezerv yaşamını zorunlu kıldı.'),
  ('Apaçi lideri Geronimo\'nun 1886\'da General Nelson Miles\'a teslim olması neyin sonu olarak kabul edilir?', 'ABD\'ye karşı örgütlü yerli silahlı direnişlerinin sonuna yakın bir dönemin', ['ABD ile Meksika arasındaki savaşın', 'İç Savaş\'ın', 'Pontiac İsyanı\'nın'], 'Geronimo\'nun teslimiyeti Güneybatı\'daki son büyük silahlı yerli direnişin sona ermesi olarak görülür.'),
  ('1924\'te Kongre\'nin kabul ettiği yasa Amerikan yerlileri için ne anlama gelmiştir?', 'Doğuştan ABD vatandaşlığı tanınması', ['Rezervlerin kaldırılması', 'Yerli dillerinin yasaklanması', 'Seçme ve seçilme hakkının kaldırılması'], 'Indian Citizenship Act, haklarını yıllarca kısıtlanmış yerlilere vatandaşlık verdi; ancak bazı eyaletlerde oy hakkı daha sonra bile engellendi.'),
  ('Pontiac\'ın 1763\'te Büyük Göller bölgesinde başlattığı isyanın temel nedeni nedir?', 'Fransız yenilgisinden sonra İngiliz egemenliği ve yerleşimci baskısından duyulan rahatsızlık', ['Kızılderili tarım ürünlerinin yasaklanması', 'Misyonerlerin okul açması', 'Yeni bir tanrıya inanmaya zorlanma'], 'İngilizlerin Fransızlar gibi hediye ve ticarette ılımlı davranmaması ve topraklara yerleşmeleri yerlileri ayaklanmaya itti.'),
  ('Dominiken rahip Bartolomé de las Casas\'ın İspanyol sömürge tarihindeki yeri aşağıdakilerden hangisinde doğru anlatılmıştır?', 'Yerli halkların ağır koşullarını yazılarıyla kınayıp haklarını savunan bir din adamı olması', ['Aztek İmparatorluğu\'nu yıkan bir komutan olması', 'Peru\'nun ilk genel valisi olması', 'Gümüş madenlerinin işletmecisi olması'], 'Las Casas, \'Hint Adaları\'nın Yıkımının Kısa Anlatısı\'nda İspanyol zulmünü anlattı; bu eser sonraki yüzyıllarda Avrupa\'da İspanya karşıtı yazılarda da kullanıldı.'),
  ('İspanyol Amerika\'sında İspanya\'da doğup sömürgeye gelen beyazlarla, sömürgede doğan beyazları ayıran sınıf ayrımı toplumda hangi gerilimi doğurdu?', 'Criollolar siyasi üst görevlerden dışlanınca peninsularesle çekişme yaşandı.', ['Peninsulareslerin yerlilere vergi vermesi', 'Mestizolar ile yerlilerin birlikte yönetime girmesi', 'Köleler ile criolloların ittifak kurması'], 'Üst görevler çoğunlukla İspanya doğumlulara verildiği için criollolar kendilerini haksız hissetti; bu durum ileride bağımsızlık hareketlerinin zeminini hazırladı.'),
  ('Sömürge döneminde Orta Amerika ve Karayipler\'de yerlilerin büyük ölçüde yok olmasındaki en önemli neden aşağıdakilerden hangisidir?', 'Çiçek, kızamık gibi Avrupa kaynaklı hastalıklar ve ağır çalışma koşulları', ['Büyük bir kıtlık ve depremler', 'Meksika\'ya göç', 'Tarım ürünlerinin yasaklanması'], 'Taíno nüfusu Hispaniola\'da birkaç on yılda neredeyse yok oldu; bağışıklık bilmedikleri hastalıklar, zorla çalıştırma ve savaş birlikte etkili oldu.'),
  ('Hispaniola\'daki ilk İspanyol yerleşimi Santo Domingo\'nun Amerika kıtasının tarihi açısından önemi nedir?', 'Kıtadaki en eski kalıcı Avrupa kenti olması', ['Meksika\'nın başkenti olması', 'Aztek imparatorunun merkezi olması', 'Cizvitlerin ilk okulunun açıldığı yer olması'], 'Santo Domingo 1496-1498 arasında kuruldu; ilk üniversite, ilk katedral ve ilk sömürge yönetim kurumları burada yer aldı.'),
  ('İspanyol sömürge yönetiminde yerli kabile liderlerine verilen \'cacique\' unvanı, yönetime nasıl katkıda bulunmuştur?', 'Yerli halk ile İspanyol yönetimi arasında aracılık yapmışlardır.', ['Doğrudan genel vali olmuşlardır.', 'Engizisyon yargıçları olmuşlardır.', 'Hacienda sahipleri olarak vergiden muaf kalmışlardır.'], 'Cacique\'ler haraç toplama ve emek sağlama işlerinde aracı oldu; böylece İspanya yerli yapıları tümüyle yıkmak yerine kullanma yoluna gitti.'),
  ('Meksika\'da 1546\'da keşfedilen Zacatecas gümüş madenlerinin sömürge ekonomisindeki sonucu aşağıdakilerden hangisidir?', 'Madencilik kentlerinin gelişmesi ve gümüşün ihracat malı olması', ['Altın standardının kalkması', 'Yerli halkın serbest ticarete geçmesi', 'Meksika\'nın Asya ticaretini bırakması'], 'Zacatecas ve Guanajuato gibi maden bölgeleri nüfus çekti; gümüş, İspanya\'nın Avrupa\'daki savaşlarını finanse eden başlıca gelir oldu.'),
  ('1494 Tordesillas Antlaşması\'nın Brezilya açısından sonucu nedir?', 'Brezilya kıyılarının Portekiz\'e düşen bölgede kalması', ['Brezilya\'nın İspanya\'ya verilmesi', 'Brezilya\'nın serbest bölge ilan edilmesi', 'Brezilya\'nın Fransa ile paylaşılması'], 'Papa\'nın arabuluculuğuyla çizilen hat, Güney Amerika\'nın doğu çıkıntısını Portekiz tarafında bıraktı; Cabral 1500\'de buraya ulaştığında hak iddia etti.'),
  ('Portekiz\'in 1534\'te Brezilya kıyısını araziler (kaptanlıklar) hâlinde soylulara dağıtmasının amacı aşağıdakilerden hangisiydi?', 'Yerleşim ve işletme masrafını özel kişilere yükleyerek bölgeyi korumak', ['Yerli halkı eğitmek', 'Kıyıyı Fransızlara satmak', 'Altın madenlerini kapatmak'], 'Taç, yerleşim ve savunmayı soylulara bırakarak maliyeti azalttı; sistem kimi yerlerde başarılı olsa da genel valilik 1549\'da kurulunca merkezileşme yoluna gidildi.'),
  ('Brezilya Prensi Pedro\'nun Portekiz Kortesi\'nin kendisini geri çağırması üzerine 1822\'de \'Kalıyorum\' (Fico) diyerek bağımsızlık yolunu açması nasıl bir gelişmedir?', 'Kan dökülmeden gerçekleşen, hanedan içinden bir bağımsızlık', ['İspanya tarzı uzun savaş', 'Cumhuriyet devrimi', 'Köylü ayaklanması'], 'Pedro, Portekiz tahtının oğlu olarak imparatorluk ilan etti; Brezilya bu yolla çok daha az çatışmayla bağımsızlığını elde etti.'),
  ('Senegal kıyısındaki Gorée Adası ve Gana kıyısındaki Elmina Kalesi hangi tarihsel olguyla ilişkilidir?', 'Atlantik köle ticaretinin merkezleri olmalarıyla', ['Osmanlı Garp Ocakları ile', 'Haçlı seferleriyle', 'Çin ipek yolu ile'], 'Bu iki yer Avrupalı tüccarların esirleri biriktirip gemilere yüklediği başlıca noktalardı; bugün anma ve miras alanı olarak korunur.'),
  ('Afrika\'da Dahomey ve Asante gibi krallıkların köle ticaretine katılmalarının nedenlerinden biri aşağıdakilerden hangisidir?', 'Karşılığında ateşli silah ve değerli mallar elde etmeleri', ['Hristiyanlığı yaymak istemeleri', 'Avrupa\'ya göç etmek istemeleri', 'Okul açmak istemeleri'], 'Ateşli silah edinen devletler komşularına üstünlük kuruyor, silah için yeniden esir yakalama savaşları yapıyordu; bu döngü bölgeyi istikrarsızlaştırdı.'),
  ('İngiltere\'de 1807\'de çıkarılan yasa neyi yasaklamıştır?', 'İngiliz gemileriyle köle ticaretini', ['Köleliğin tümünü', 'Pamuk ve şeker ihracatının tamamını', 'Şeker ithalatını'], '1807 yasası ticareti yasaklamış, sömürgelerde kölelik kurumu ise 1833 tarihli yasayla kaldırılmıştır.'),
  ('1839\'da \'La Amistad\' gemisinde esir Afrikalıların isyan etmesinin sonrasında ABD mahkemelerinde nasıl bir karar verilmiştir?', 'Esirlerin özgür oldukları kabul edilerek Afrika\'ya dönmelerine izin verilmiştir.', ['Esirler köle olarak İspanya\'ya teslim edilmiştir.', 'Esirler idam edilmiştir.', 'Esirler Küba\'ya geri gönderilmiştir.'], 'Yüksek Mahkeme, esirlerin yasa dışı ticaretle kaçırıldığını kabul etti; olay kölelik karşıtı hareketi güçlendirdi.'),
  ('Sierra Leone\'nin başkenti Freetown\'un kuruluş amacı nedir?', 'Serbest bırakılan eski köleler için yerleşim yeri oluşturmak', ['Altın madenlerini işletmek', 'Askerî üs kurmak', 'Kahve ticaretini geliştirmek'], '18. yüzyılın sonunda İngiliz kölelik karşıtlarının desteğiyle kurulan Freetown, azat edilen siyahların yerleştiği kent oldu.'),
  ('Karayipler\'de Barbados ve Jamaika\'daki şeker plantasyonlarında beyaz kamış sahiplerinin zenginleşmesi aşağıdakilerden hangisinin sonucudur?', 'Köle emeğinin yoğun kullanılması', ['Yerli halkın ücretli çalışması', 'Kuzey Amerika\'dan ucuz şeker ithalatı', 'Büyük ölçekli makineleşme'], 'Şeker plantasyonları çok işçi gerektirdiği için adalar nüfusunun büyük çoğunluğu köle olmuştu; bu düzen İngiltere\'nin zenginleşmesine katkıda bulunmuştur.'),
  ('John Winthrop\'un 1630\'da Massachusetts Körfezi\'ne gelen Puritanlara yönelik \'tepedeki şehir\' konuşması kolonilerin kuruluş amacı hakkında ne söylemektedir?', 'Dinî bir toplumu dünyaya örnek olacak biçimde kurma çabası', ['Kolonilerin hemen bağımsızlığını', 'Sadece ticaret yapma isteğini', 'Yerlileri yok etme zorunluluğunu'], 'Puritanlar, İngiltere\'deki kilise düzenini yetersiz bularak ahlaki bakımdan örnek bir cemaat kurmayı hedefledi.'),
  ('Roger Williams\'ın Massachusetts\'ten sürülmesinin ardından kurduğu Rhode Island kolonisinin ayırt edici özelliği nedir?', 'Din özgürlüğünü ve kilise-devlet ayrımını benimsemesi', ['Yalnız Anglikanlara açık olması', 'Köleliğin zorunlu tutulması', 'Kralın doğrudan yönetmesi'], 'Williams, Puritan kolonisindeki dinî baskıyı eleştirdi; Rhode Island farklı mezheplere ve Yahudilere kapı açtı.'),
  ('Yeni İngiltere, Orta ve Güney bölgeleri arasındaki ekonomik farklara ilişkin hangisi doğrudur?', 'Güney\'de büyük tarım plantasyonları, Yeni İngiltere\'de ise denizcilik ve küçük çiftçilik öne çıkmıştır.', ['Üç bölgede de plantasyon hâkimdi.', 'Yalnız Yeni İngiltere\'de köle çalıştırılmıştır.', 'Orta bölgede hiç tarım yoktu.'], 'İklim ve toprak farkı Güney\'de tütün, pirinç ve çivit plantasyonlarını, Kuzey\'de ise balıkçılık, gemi yapımı ve ticareti doğurdu; bu fark ileride Kuzey-Güney ayrımına dönüşecekti.'),
  ('1763 Paris Antlaşması\'nın Kuzey Amerika açısından sonucu aşağıdakilerden hangisidir?', 'Fransa\'nın Kanada\'yı İngiltere\'ye bırakması', ['İngiltere\'nin on üç kolonisini kaybetmesi', 'İspanya\'nın Florida\'yı alması', 'Kolonilere bağımsızlık verilmesi'], 'Yedi Yıl Savaşları\'nın bitişinde Fransa Kuzey Amerika\'daki topraklarının büyük kısmını yitirdi; kolonistlerin Fransız tehdidi kalmadı.'),
  ('Amerikan kolonilerinde 1730-1740\'larda yaşanan \'Büyük Uyanış\' hareketinin etkisi neydi?', 'Kolonileri ortak bir dinî coşku çatısı altında birleştirmesi', ['Yerli halkın Hristiyanlığa geçişini yasaklaması', 'Kilise vergilerinin artırılması', 'Bağımsızlık ilanı'], 'Vaizlerin dolaşıp halka seslenmesi, kolonilerde ortak bir kimlik oluşturdu ve geleneksel dinî otoritenin sorgulanmasını yaygınlaştırdı.'),
  ('1765 Damga Yasası\'na kolonilerde gösterilen tepkinin en önemli sonucu aşağıdakilerden hangisidir?', 'Koloniler arası ilk ortak örgütlenme ve İngiliz mallarını boykot', ['Kolonilerin kralla barış yapması', 'Yasanın kolonilerde sessizce kabul edilmesi', 'Kolonilerin Fransa ile birleşmesi'], 'Gazete ve resmî belgelere pul zorunluluğu getiren yasa, Damga Yasası Kongresi\'nin toplanmasına ve İngiliz mallarının boykotuna yol açtı; yasa 1766\'da kaldırıldı.'),
  ('Nisan 1775\'te Massachusetts\'te başlayan ve Amerikan Bağımsızlık Savaşı\'nın ilk silahlı çatışmaları sayılan olaylar hangileridir?', 'Lexington ve Concord çatışmaları', ['Saratoga ve Yorktown muharebeleri', 'Bunker Hill ve Brooklyn Kuşatması', 'Trenton ve Princeton baskınları'], 'İngiliz birlikleri silah deposunu ele geçirmek için Concord\'a yürürken milis güçleriyle karşılaştı; savaş fiilen başlamış oldu.'),
  ('Ocak 1776\'da yayımlanan \'Sağduyu\' (Common Sense) broşürünün Amerikan kamuoyundaki etkisi nedir?', 'Krala bağlılığı sorgulatıp bağımsızlık fikrini geniş kitlelere yaymıştır.', ['Kolonilerin barışa yönelmesini sağlamıştır.', 'Kölelik karşıtlığını başlatmıştır.', 'Vergi yasalarını kaldırmıştır.'], 'Thomas Paine\'in sade dille yazdığı broşür yüz binlerce satarak bağımsızlığı yalnızca aydınların değil halkın da konusu yaptı.'),
  ('Ekim 1777\'de Saratoga\'da İngiliz ordusunun teslim olmasının Amerikan Devrimi\'ne en önemli katkısı nedir?', 'Fransa\'nın ittifakı kabul edip açıkça yardım etmesi', ['İngiltere\'nin kolonilere bağımsızlık tanıması', 'Kıta Kongresi\'nin dağılması', 'Washington\'ın görevden alınması'], 'Saratoga zaferi Paris\'e Amerikalıların kazanabileceğini gösterdi; 1778\'de Fransa ittifak anlaşmasıyla savaşa girdi.'),
  ('Fransız aristokrat Marquis de Lafayette\'in Amerikan Devrimi\'ndeki rolü nedir?', 'Washington\'ın yanında dövüşen gönüllü subay olması', ['İngiliz generali olması', 'Kıta Kongresi başkanı olması', 'Fransız kralının elçisi olması'], 'Lafayette 19 yaşında Amerika\'ya gelip Kıta Ordusu\'nda görev aldı; sonradan Fransız Devrimi\'nde de önemli rol oynadı.'),
  ('1783 Paris Antlaşması\'nın kapsamı ile ilgili hangisi doğrudur?', 'İngiltere ABD\'nin bağımsızlığını tanıdı ve sınırı Mississippi\'ye kadar genişletti.', ['İngiltere Kanada\'yı ABD\'ye bıraktı.', 'Kolonilere özerklik tanındı.', 'ABD İngiltere\'ye savaş tazminatı ödedi.'], 'Antlaşma, savaşın hukuken sona erdiğini gösterir; yeni devlet Büyük Göller\'den Florida\'ya, Atlantik\'ten Mississippi\'ye uzanan bir toprağa sahip oldu.'),
  ('1781\'de yürürlüğe giren Konfederasyon Maddeleri\'nin başlıca zayıflığı nedir?', 'Merkezî hükümetin vergi koyma ve ticareti düzenleme yetkisinin bulunmaması', ['Çok güçlü bir cumhurbaşkanı öngörmesi', 'Eyaletlerin varlığını reddetmesi', 'Anayasa mahkemesi kurması'], 'Kongre eyaletlerden zorla vergi alamıyor, ordu için kaynak bulmakta zorlanıyordu; Shays İsyanı (1786) bu sorunu gösterdi.'),
  ('1787 Philadelphia Konvansiyonu\'ndaki \'Büyük Uzlaşma\' (Connecticut Uzlaşması) neyi çözmüştür?', 'Büyük ve küçük eyaletlerin kongredeki temsil dengesini', ['Kölelik sorununu tümüyle', 'Başkanın seçim biçimini', 'Yargıçların atanma yöntemini'], 'Temsilciler Meclisi nüfusa göre, Senato ise her eyalete eşit sayıda üye ile kuruldu; böylece büyük-küçük eyalet tartışması çözüldü.'),
  ('Anayasa\'nın kabulü sırasında bir hak bildirisinin eksikliğini eleştiren Anti-Federalistlerin talebi nasıl sonuçlanmıştır?', '1791\'de ilk on değişikliğin (Haklar Bildirisi) anayasaya eklenmesiyle', ['Anayasanın iptal edilmesiyle', 'Eyaletlerin federasyondan ayrılmasıyla', 'Başkanın yetkilerinin kaldırılmasıyla'], 'İfade, din ve basın özgürlüğü ile adil yargılanma gibi hakları güvence altına alan ilk on ek madde Haklar Bildirisi olarak bilinir.'),
  ('Marbury v. Madison (1803) kararının Amerikan hukuk tarihindeki önemi nedir?', 'Yüksek Mahkeme\'nin yasaları anayasaya aykırılık yönünden denetleme yetkisini kurması', ['Başkanın yargıçları azletme yetkisini tanıması', 'Kölelik kurumunu kaldırması', 'Kongre\'nin eyaletleri yönetmesini sağlaması'], 'Başkan Yargıç Marshall, mahkemenin anayasaya aykırı yasaları geçersiz sayabileceğini belirleyerek yargı denetiminin temelini attı.'),
  ('Washington\'ın 1796 Veda Konuşması\'nda ABD\'ye öğütlediği dış politika çizgisi aşağıdakilerden hangisidir?', 'Avrupa devletleriyle kalıcı ittifaklardan kaçınmak', ['Fransa ile sürekli ittifak yapmak', 'Avrupa\'ya asker göndermek', 'Britanya Krallığı\'na katılmak'], 'Washington siyasi kutuplaşmayı ve Avrupa\'nın çekişmelerine bulaşmayı sakıncalı gördü; bu görüş uzun süre ABD dış politikasını etkiledi.'),
  ('1804-1806\'da Louisiana topraklarını araştırmak için Jefferson\'ın görevlendirdiği Lewis ve Clark seferinin amaçlarından biri neydi?', 'Pasifik\'e ulaşan bir yolu bulmak ve bölgeyi tanımak', ['Aztek hazinesini bulmak', 'Yerlileri sürmek', 'Kanada\'yı fethetmek'], 'Sefer, Missouri Nehri\'ni izleyip Pasifik kıyısına ulaştı; haritalar çıkardı, yerli halklarla temas kurdu ve batı genişlemesine zemin hazırladı.'),
  ('1812 Savaşı\'nı bitiren 1814 Gent Antlaşması\'nın içeriği hakkında hangisi doğrudur?', 'Savaş öncesi sınırlar esas alınarak toprak değişikliği yapılmadı.', ['ABD, Kanada\'yı ilhak etti.', 'İngiltere ABD\'ye tazminat ödedi.', 'ABD bağımsızlığını yitirdi.'], 'Savaşın belirgin kazananı olmadı; ancak ABD, İngiltere\'ye karşı ayakta kalarak ulusal özgüven kazandı.'),
  ('1820 Missouri Uzlaşması\'nın düzenlemesi aşağıdakilerden hangisidir?', 'Missouri köleci, Maine özgür eyalet olarak katıldı; batıda belli enlemin kuzeyinde kölelik yasaklandı.', ['Kölelik bütün eyaletlerde yasaklandı.', 'Tüm yeni eyaletler köleci olacaktı.', 'Missouri Meksika\'ya bırakıldı.'], 'Köleci ve özgür eyaletlerin Senato\'daki dengesini korumak için yapılan uzlaşma, 36°30\' kuzey enleminin kuzeyinde kölelik yasağı getirdi.'),
  ('John O\'Sullivan\'ın 1845\'te kullandığı \'Manifest Destiny\' (Apaçık Kader) ifadesi hangi görüşü dile getirir?', 'ABD\'nin kıtayı Atlantik\'ten Pasifik\'e kadar kaplamaya yazgılı olduğu görüşünü', ['ABD\'nin Avrupa\'ya müdahale etmesi gerektiği görüşünü', 'Kölelik kurumunun korunması gerektiği görüşünü', 'Yerli halklarla barışın şart olduğu görüşünü'], 'Bu fikir, batıya yayılmayı ilahi bir hak ve görev gibi göstererek Texas, Oregon ve Kaliforniya\'nın ilhakını meşrulaştırdı.'),
  ('Harriet Beecher Stowe\'un 1852\'de yayımlanan \'Tom Amca\'nın Kulübesi\' romanının kamuoyuna etkisi nedir?', 'Kuzey\'de kölelik karşıtı duyarlılığı güçlendirmesi', ['Güney\'de köleliğe desteğin azalması', 'Kaçak Köle Yasası\'nın kalkması', 'Yerlilerin vatandaşlık alması'], 'Roman, kölelik düzeninin acılarını ayrıntılı biçimde anlatarak Kuzey\'de çok okundu ve köleliğe karşı tutumları sertleştirdi.'),
  ('1854 Kansas-Nebraska Yasası\'nın \'halk egemenliği\' ilkesiyle yeni topraklarda köleliğin sorunu neye bırakılmıştır?', 'Bölgede yaşayan halkın oylamasına', ['Federal Yüksek Mahkemenin tek başına kararına', 'Başkanın tek başına kararına', 'Meksika hükümetinin onayına'], 'İlke, Missouri Uzlaşması\'ndaki sınırı fiilen kaldırdı; Kansas\'ta kölelik yanlıları ile karşıtları arasında kanlı çatışmalar çıktı.'),
  ('Dred Scott davasında (1857) Yüksek Mahkeme siyah Amerikalılar hakkında hangi karara varmıştır?', 'Siyahların vatandaş sayılamayacağına ve kölelerin mülk olduğuna', ['Köleliğin yasadışı olduğuna', 'Özgür siyahların oy hakkı olduğuna', 'Kölelerin seçmen sayılacağına'], 'Başkan Yargıç Taney, Afrika kökenlilerin anayasanın koruduğu vatandaşlar olmadığını belirtti; karar Kuzey\'de büyük öfke yarattı.'),
  ('Kölelik karşıtı John Brown\'ın 1859\'da Virginia\'daki Harpers Ferry\'de silah deposuna baskın yapmasının amacı neydi?', 'Köleleri silahlandırıp isyan başlatmak', ['Güney\'in bağımsızlığını ilan edip Kuzey\'e saldırmak', 'Federal parayı ele geçirmek', 'Yerli halkla ittifak kurmak'], 'Baskın başarısız oldu ve Brown idam edildi; olay Güney\'de korku, Kuzey\'de ise kölelik karşıtları arasında tartışma yarattı.'),
  ('1 Ocak 1863 tarihli Özgürlük Bildirgesi (Emancipation Proclamation) neyi ilan etmiştir?', 'İsyan hâlindeki eyaletlerdeki kölelerin özgür sayıldığını', ['Bütün ABD\'de köleliğin kalktığını', 'Savaşın bittiğini', 'Güney\'e af verildiğini'], 'Bildirge sadece Konfederasyon\'un denetimindeki yerleri kapsıyordu; yine de savaşın amacını köleliğin sonuna yöneltti ve siyahların orduya katılmasını sağladı.'),
  ('Lincoln\'ün Gettysburg Konuşması\'ndaki \'halkın, halk tarafından, halk için hükümeti\' ifadesi neyi savunur?', 'Demokrasinin korunması ve özgürlük ideallerinin sürmesi', ['Güney\'in ayrılma hakkını', 'Kralın yönetimini', 'Askerî diktatörlüğü'], 'Kısa konuşma, savaşı yalnızca birliği korumak değil, eşitlik ve halk yönetimi ideallerini yaşatmak olarak tanımladı.'),
  ('ABD Anayasası\'na eklenen 14. değişikliğin getirdiği temel düzenleme nedir?', 'ABD\'de doğanlara vatandaşlık ve yasalar önünde eşit korunma', ['Kadınlara oy hakkı', 'İçki yasağı', 'Gelir vergisi'], 'Madde 1868\'de kabul edildi ve eski kölelerin vatandaşlığını güvenceye aldı; sonraki yüzyılda sivil haklar davalarında temel dayanak oldu.'),
  ('1862 tarihli Homestead (Yurtluk) Yasası ile batıya yerleşecek vatandaşlara hangi hak tanınmıştır?', 'Belirli süre ekip biçmeleri koşuluyla hemen hemen bedelsiz arazi sahibi olma', ['Devlet memurluğu', 'Vergisiz ticaret', 'Hazine tahvili alma önceliği'], 'Yasa, beş yıl ikamet ve işleme karşılığında yaklaşık 160 akre arazi verdi; Batı\'nın hızla yerleşime açılmasını sağladı.'),
  ('1882 Çinli Dışlama Yasası ABD göç politikasında hangi dönüm noktasını oluşturmuştur?', 'Belirli bir etnik gruba karşı göçün ilk kez yasaklanması', ['Tüm göçmenlerin kabul edilmesi', 'Çin ile ticaretin durması', 'Göçmen sayısının artması'], 'Yasa, Kaliforniya\'daki ucuz işgücü gerilimi ve ırkçılık sonucu çıktı; ABD\'nin ülkeye giriş politikalarında seçici dönemi başlattı.'),
  ('Mark Twain\'in adlandırdığı \'Yaldızlı Çağ\' (Gilded Age) ifadesi 19. yüzyıl sonu ABD için neyi eleştirir?', 'Parlak servet gösterisinin altındaki yolsuzluk ve toplumsal eşitsizliği', ['Sanayinin tamamen geri kalmasını', 'Köleliğin yeniden başlamasını', 'Ülkenin altın standardını terk etmesini'], 'Rockefeller ve Carnegie gibi isimlerle anılan hızlı sanayileşme dönemi, yüzeyde parıltılı görünse de işçi yoksulluğu ve siyasi yolsuzlukla doluydu.'),
  ('1890 Sherman Antitröst Yasası\'nın amacı nedir?', 'Tekelleşmeyi ve ticareti kısıtlayan birlikleri sınırlamak', ['Gümrük vergilerini artırmak', 'İşçi grevlerini yasaklamak', 'Altın standardını getirmek'], 'Yasa, Standard Oil gibi dev şirket birleşmelerine karşı rekabeti korumayı hedefledi; uygulaması başlangıçta zayıf kaldı.'),
  ('1898\'de Havana limanında ABD savaş gemisi Maine\'in patlayıp batması hangi sonuca yol açmıştır?', 'ABD\'nin İspanya\'ya savaş ilan etmesine', ['İspanya\'nın Küba\'yı ABD\'ye satmasına', 'İspanya\'nın Küba\'dan çekilmesine', 'Meksika ile savaşa'], 'Sarı basının İspanya\'yı suçlayan haberleriyle kamuoyu savaşa yöneldi; Nisan 1898\'de savaş başladı.'),
  ('1899-1902 Filipin-Amerikan Savaşı\'nın nedeni nedir?', 'Filipinlilerin ABD egemenliğini kabul etmeyip bağımsızlıkta ısrar etmesi', ['Filipinlilerin İspanya\'ya yeniden katılması', 'Japonya\'nın adaları işgali', 'Filipinlilerin ABD\'ye katılma isteği'], 'İspanya\'dan kurtulan Filipinliler Aguinaldo önderliğinde cumhuriyet kurmuştu; ABD\'nin adalara sahip çıkması çatışmaya yol açtı.'),
  ('Hawaii Krallığı\'nın son hükümdarı Kraliçe Liliuokalani\'nin 1893\'te devrilmesinde hangi grubun payı büyüktür?', 'ABD kökenli plantasyon sahipleri ve işadamlarının', ['İngiliz askerlerinin', 'Japon göçmenlerin', 'Yerli rahiplerin'], 'Amerikalı işadamları Amerikan deniz piyadelerinin desteğiyle krallığı devirdi; 1898\'de adalar ABD\'ye ilhak edildi.'),
  ('1903\'te Panama\'nın Kolombiya\'dan ayrılmasında ABD\'nin rolü nedir?', 'Kanal bölgesini elde etmek için ayrılıkçıları donanmayla desteklemiştir.', ['İki ülkeyi barıştırmıştır.', 'Panama\'ya karşı ambargo uygulamıştır.', 'Kolombiya ile birleşmesini desteklemiştir.'], 'Başkan Theodore Roosevelt kanal yapımı için Kolombiya\'yı baskı altında tutmuş, ayrılıkçı Panama\'yı hemen tanımıştır.'),
  ('1867 Britanya Kuzey Amerika Yasası ile Kanada\'nın ilk federal yapısını oluşturan eyaletler hangileridir?', 'Ontario, Quebec, Nova Scotia ve New Brunswick', ['Alberta, Manitoba ve British Columbia', 'Newfoundland ve Quebec', 'Yukon ve Ontario'], 'Dominyon, Ontario ve Quebec\'in ayrılmasıyla iki dilli bir yapı kazandı; diğer bölgeler sonradan katıldı.'),
  ('Latin Amerika\'daki bağımsızlık hareketlerini hızlandıran 1808 gelişmesi aşağıdakilerden hangisidir?', 'Napolyon\'un İspanya\'yı işgal edip kralı tahttan indirmesi', ['Kolomb\'un ikinci yolculuğu', 'İngiltere\'nin Haiti\'yi işgali', 'Fransız Devrimi\'nin başlaması'], 'Kral VII. Ferdinand\'ın tahttan uzaklaştırılması sömürgelerde meşru yönetim sorununa yol açtı; yerel yönetim kurulları (juntalar) kuruldu ve bağımsızlık fikri güçlendi.'),
  ('Rahip Miguel Hidalgo\'nun 16 Eylül 1810\'da Dolores kasabasında yaptığı çağrı Meksika\'da neye yol açmıştır?', 'Bağımsızlık savaşının başlamasına', ['Meksika İmparatorluğu\'nun kurulmasına', 'Cizvitlerin sürülmesine', 'Hacienda sisteminin kaldırılmasına'], '\'Dolores Çağrısı\' yerli ve melez köylüleri ayaklandırdı; bu tarih Meksika\'nın ulusal bağımsızlık günü olarak kutlanır.'),
  ('1819\'da Boyacá zaferiyle Bolívar\'ın kurtardığı ve ardından kurulan \'Büyük Kolombiya\' hangi ülkeleri kapsıyordu?', 'Venezuela, Yeni Granada (Kolombiya) ve Ekvador', ['Peru, Bolivya ve Şili', 'Arjantin, Uruguay ve Paraguay', 'Meksika ve Orta Amerika'], 'Bolívar\'ın hayali olan bu birlik, bölgesel çıkar çatışmaları nedeniyle 1830\'da dağıldı.'),
  ('1824\'te Peru\'daki Ayacucho Savaşı\'nın önemi nedir?', 'Güney Amerika\'daki İspanyol egemenliğinin son büyük savaşı olması', ['Meksika\'nın bağımsızlığı', 'Brezilya\'nın bağımsızlığı', 'Fransa\'nın yenilmesi'], 'Bolívar adına komuta eden Antonio José de Sucre, kıtadaki son büyük İspanyol ordusunu yendi.'),
  ('Latin Amerika bağımsızlıklarından sonra ortaya çıkan \'caudillo\' yönetimi için aşağıdakilerden hangisi doğrudur?', 'Silahlı destekçilere dayalı yerel güçlü liderlerin yönetimidir.', ['Meclisin seçtiği hükümdardır.', 'Yerli kabilelerin konseyidir.', 'İspanyol kralının valisidir.'], 'Merkezî devlet kurumlarının zayıf olduğu yeni ülkelerde yerel güçlü adamlar orduları ve toprak sahipleri aracılığıyla iktidarı ele geçirdi.'),
  ('1879-1883 Pasifik Savaşı\'nın bir sonucu olarak Bolivya hangi kaybı yaşamıştır?', 'Pasifik kıyısını', ['Amazon havzasındaki bütün topraklarını', 'Başkentini', 'Bağımsızlığını'], 'Şili, Peru ve Bolivya ile güherçile bölgesi yüzünden savaştı; Antofagasta\'yı alarak Bolivya\'yı denizden yoksun bıraktı.'),
  ('Benito Juárez\'in önderlik ettiği 1850\'ler Meksika \'Reforma\' hareketi neyi hedeflemiştir?', 'Kilise ve ordu ayrıcalıklarını sınırlayıp yasa önünde eşitliği getirmeyi', ['Meksika\'yı İspanya\'ya bağlamayı', 'Hacienda sistemini güçlendirmeyi', 'Kilise toprağını artırmayı'], 'Juárez\'in yasaları, kilisenin toprak mülkiyetini ve özel mahkemelerini ortadan kaldırarak laik bir devlet kurmayı amaçladı.'),
  ('Porfirio Díaz\'ın 1876-1911 arasındaki uzun yönetimi için aşağıdakilerden hangisi söylenebilir?', 'Ekonomik gelişme sağlanırken siyasi muhalefetin ve köylü haklarının ezildiği bir diktatörlüktür.', ['Köylülere büyük toprak dağıttığı bir demokrasidir.', 'Kilisenin tamamen kaldırıldığı bir dönemdir.', 'Fransız yönetiminin devamıdır.'], 'Demiryolu ve yabancı yatırım arttı; buna karşılık toprak sahipleri güçlendi, seçimler denetlendi ve 1910 devrimi bu öfkeden doğdu.'),
  ('José Martí\'nin Küba bağımsızlık mücadelesindeki rolü aşağıdakilerden hangisidir?', 'Kuzeyde Küba Devrim Partisi\'ni kurup 1895 ayaklanmasını örgütlemesi', ['Meksika\'nın ilk cumhurbaşkanı olması', 'İspanya\'nın genel valisi olması', 'Haiti\'nin kurucusu olması'], 'Martí şair ve düşünürdü; 1895\'te Küba\'ya döndü ve kısa sürede öldü, ama bağımsızlık sembolü oldu.'),
  ('Aksum Kralı Ezana\'nın 4. yüzyılda Hristiyanlığı kabul etmesinin siyasi sonucu nedir?', 'Aksum\'un Roma-Bizans dünyasıyla bağlarının kuvvetlenmesi', ['Sahra ticaret yollarının kesilmesi ve devletin Mısır\'a bağımlı hâle gelmesi', 'Mısır ile savaş başlaması', 'Kızıldeniz\'in kapatılması'], 'Rahip Frumentius\'un etkisiyle Hristiyanlık devlet dini oldu; Aksum paralarının üzerine haç basıldı ve Bizans\'la ticaret ilişkisi gelişti.'),
  ('Aksum Krallığı\'nın ticaret ve zenginliğinde Adulis limanının işlevi nedir?', 'Fildişi ve altını Kızıldeniz\'e ve Akdeniz dünyasına açan liman olması', ['Karadeniz ticaretinin merkezi olması', 'Sahra altın yolunun çıkış noktası olması', 'Hint Okyanusu\'ndaki Zanzibar ve Kilwa limanlarına bağlanan başlıca hat olması'], 'Adulis, Aksum\'u Roma, Hindistan ve Arabistan ile bağlayan liman kentiydi; krallık para basan birkaç Afrika devletinden biriydi.'),
  ('Aksum\'un kendine özgü bir yazı ve yapı geleneği vardır. Aşağıdakilerden hangisi bu geleneğin ürünüdür?', 'Taştan oyulmuş dikilitaşlar', ['Kerpiçten yapılmış basamaklı tapınak piramitleri', 'Kil tabletler', 'Rüzgârlı Zimbabve duvarları'], 'Aksum\'un dev dikilitaşları soylu mezarlarını işaretliyordu; Ge\'ez yazısı da burada geliştirilen yazı sistemlerinden biridir.'),
  ('Etiyopya İmparatoru Haile Selassie 1936\'da Milletler Cemiyeti\'nde yaptığı konuşmada hangi konuya dikkat çekmiştir?', 'İtalyan işgalinde zehirli gaz kullanılmasına ve toplu güvenliğin çöküşüne', ['Etiyopya\'nın cemiyete katılma isteğine ve Mısır ile ittifak kurma planına', 'Mısır ile sınır sorununa', 'Sömürge yönetiminin savunulmasına'], 'İmparator, İtalyan gaz saldırılarını anlatıp uluslararası toplumdan yardım istedi; cemiyetin yaptırım uygulayamaması onun zayıflığını gösterdi.'),
  ('Nubya\'nın Antik Çağ\'da Mısır ile ilişkileri hakkında hangisi doğrudur?', 'Mısır\'a altın, fildişi ve asker sağlayan, zaman zaman Mısır\'ı yöneten komşu bir uygarlıktı.', ['Nubya, Mısır\'a her dönemde tümüyle boyun eğmiş bir eyaletiydi.', 'Nubya, Mısır ile hiç temas etmedi.', 'Nubya, Mısır\'dan yazıyı öğrenemedi.'], 'Nubya\'daki Kerma ve Kuş krallıkları zaman zaman Mısır\'a boyun eğse de bağımsız siyasi gelenek geliştirmiş, bir dönem Mısır\'ı fethetmiştir.'),
  ('Aksum yazı geleneğinin devamı olan Ge\'ez dilinin bugün Etiyopya\'daki başlıca kullanım alanı aşağıdakilerden hangisidir?', 'Etiyopya Ortodoks Kilisesi\'nin ayin dili', ['Yalnızca mahkemelerde ve resmî yazışmalarda kullanılan dil', 'Okullarda anadil', 'Ticaret dili'], 'Ge\'ez günlük konuşma dili olmaktan çıktı; ancak kilise ayinlerinde ve yazı kültüründe canlı kalmıştır.'),
  ('Batı Afrika\'da griot adı verilen kişiler toplumda hangi görevi üstlenir?', 'Sözlü tarihi, soyağaçlarını ve destanları ezbere aktarırlar.', ['Hükümdarın vergi memuru olarak çalışıp haraç defterlerini yazılı tutarlar.', 'Kervanların yol rehberliğini yapıp deve sürülerini yönetirler.', 'Kutsal ormanlarda tarım ayinleri yönetirler.'], 'Yazılı kayıtların sınırlı olduğu toplumlarda griotlar hükümdarlık soylarını ve olayları sözlü olarak yaşatan hafızaydı.'),
  ('Mansa Musa\'nın 1324-1325 hac yolculuğunda Kahire\'ye çok miktarda altın getirmesinin sonucu neydir?', 'Altın değerinin geçici olarak düşmesi ve Mali\'nin Akdeniz dünyasında tanınması', ['Mısır Memlük Devleti\'nin Mali\'ye bağlanıp vergi ödemeye başlaması ve sultanın tahttan inmesi', 'Altın madenlerinin kapatılması', 'Memlük sultanının hacca gitmesi'], 'Musa\'nın cömert harcamaları Kahire\'de altın fiyatını düşürdü; Mali, Avrupa haritalarında da zengin bir ülke olarak gösterildi.'),
  ('Faslı gezgin İbn Battuta\'nın 1352-1353\'te Mali\'yi ziyaret ettiğinde bölgeyle ilgili tuttuğu notların tarih açısından önemi nedir?', 'İmparatorluğun düzeni ve halkının yaşamı hakkında yazılı bir tanıklık sunması', ['Mali\'nin Avrupalı devletlerle yaptığı ticaret antlaşmalarını belgelemesi', 'Sahra\'nın haritasını çıkarması', 'Mali\'nin Avrupa\'ya düzenlediği seferleri anlatması'], 'İbn Battuta, Mali\'de güvenliği ve adaleti övdü, bazı geleneklerden hoşnut olmadığını da yazdı; metni dönemin başlıca kaynaklarındandır.'),
  ('Songhay Hükümdarı Sonni Ali\'nin 15. yüzyılın sonlarında yaptığı en önemli askerî başarı nedir?', 'Timbuktu ve Cenne gibi ticaret kentlerini ele geçirerek Nijer boyunu birleştirmek', ['Mısır\'ı fethedip Nil Vadisi\'ni Songhay topraklarına katmak', 'Sahra\'nın kuzeyindeki Fas\'ı işgal etmek', 'Atlantik kıyısına ulaşmak'], 'Sonni Ali, nehir donanması ve süvarisiyle Mali\'nin eski topraklarını Songhay\'a bağlayıp Gao merkezli geniş bir devlet kurdu.'),
  ('1591\'de Fas Sultanı Ahmed el-Mansur\'un ordusunun Songhay İmparatorluğu\'nu Tondibi\'de yenmesinde belirleyici etken hangisidir?', 'Fas ordusunun ateşli silahlar ve topla donatılmış olması', ['Songhay\'da yeni bir hanedanın kurulup ordunun ikiye bölünmesi', 'Mısır\'ın Songhay\'a yardımı', 'Sahra\'nın kuruması'], 'Songhay\'ın mızrak ve ok ağırlıklı ordusu, tüfek taşıyan Fas birliğine karşı çaresiz kaldı; imparatorluk dağıldı.'),
  ('Bugünkü Nijerya\'daki Benin Krallığı\'nın sanat tarihindeki önemi hangi eserlerle bilinir?', 'Pirinç ve bronz plaketler ile baş heykelleri', ['Kayaya oyulmuş anıtsal kiliseler ve taş piramitler', 'Kaya kiliseleri', 'Papirüs parşömenleri'], 'Benin\'in saray sanatı, hükümdar (Oba) ve saray yaşamını betimleyen bronzlar yaptı; 1897\'de İngilizlerin yağması sonucu birçoğu Avrupa müzelerine dağıldı.'),
  ('Dahomey Krallığı\'nın ordusunda yer alan ve Avrupalı gözlemcilerce \'Amazonlar\' olarak adlandırılan birlik hangisidir?', 'Kadın savaşçılardan oluşan Mino (Agojie) birliği', ['Yaşlı komutanlardan oluşan danışma birliği', 'Yabancı paralı askerler', 'Deniz piyadeleri'], 'Dahomey\'in kadın birliği 19. yüzyılda Fransızlara karşı da savaştı; 1894\'te krallık Fransa\'ya yenildi.'),
  ('Taghaza maden ocaklarından çıkarılan tuzun Batı Afrika ticaretindeki önemi nedir?', 'Tropik bölgede tuz sıkıntısını gidermesi ve altınla değiştirilmesi', ['Yalnız süs eşyası olması', 'Mısır\'a satılan baharat olması', 'Yerel madenî paranın yerini alıp ihracat kalemi olması'], 'Güneyde tuz kıt, kuzeyde altın azdı; tuz ve altın takası Sahra ötesi ticaretin temelini oluşturdu.'),
  ('Songhay ve Mali dönemlerinde Timbuktu\'daki Sankore medresesinin işlevi nedir?', 'Hukuk, ilahiyat ve astronomi gibi alanlarda öğrenim veren bir bilim merkezi olması', ['Altın ve tuz madenlerinin işletildiği büyük bir ocak olması ve vergi toplaması', 'Kervan limanı olması', 'Kraliyet mezarlığı olması'], 'Timbuktu, el yazması eser üretimi ve ticaretiyle ünlendi; bugün hâlâ korunan binlerce el yazması vardır.'),
  ('Yaklaşık MÖ 1000\'den itibaren Orta ve Güney Afrika\'ya yayılan Bantu konuşan toplulukların beraberinde getirdiği temel yenilik hangisidir?', 'Demir işçiliği ve yerleşik tarım', ['Yazıyla kaydedilen yasalar ve taş tapınaklar, ayrıca at biniciliği', 'Atlı savaş arabaları ile geniş sulama kanalları', 'Deniz ticaretine dayalı kent devletleri ve liman düzeni'], 'Bantu göçleri demir silah ve aletleri, darı-sorgum tarımı ve sığır yetiştiriciliğini yayarak kıtanın dil ve nüfus haritasını değiştirdi.'),
  ('1652\'de Cape Town bölgesine ilk Avrupa yerleşimini kuran Jan van Riebeeck hangi kuruluşun görevlisiydi?', 'Hollanda Doğu Hindistan Şirketi', ['İngiliz Doğu Hindistan Şirketi', 'Portekiz Kraliyeti\'nin Sagres Denizcilik Okulu ve Lizbon Konseyi', 'Fransız Hint Şirketi'], 'Yerleşim, Hindistan yolundaki gemileri taze erzakla donatmak için kurulmuştu; zamanla Boer topluluğuna dönüştü.'),
  ('Boerlerin 1830\'lardan itibaren Cape Kolonisi\'nden iç bölgelere yaptığı Büyük Trek\'in nedenlerinden biri nedir?', 'İngiliz yönetiminden ve köleliğin kaldırılmasından rahatsızlık duymaları', ['Hollanda\'nın onları geri çağırması', 'Witwatersrand\'da bulunan altın yatakları nedeniyle iç bölgelere akın etmeleri', 'Zulu krallığıyla ittifak kurmak istemeleri'], '1834\'te İngiltere\'nin kölelik yasasının Cape\'te uygulanması ve İngiliz hukuku Boer çiftçilerini göçe itti.'),
  ('1867\'de Kimberley yakınlarında elmas bulunmasının Güney Afrika ekonomisine etkisi nedir?', 'Madencilik sanayisini ve göçü hızlandırması', ['Tarımın ortadan kalkması', 'Boer ile Zulu krallıkları arasında kalıcı bir barış antlaşması yapılması', 'Kıyı ticaretinin durması'], 'Elmas humması binlerce göçmeni ve yatırımcıyı çekti; Cecil Rhodes\'un De Beers şirketi 1888\'de bölgeyi tekelleştirdi.'),
  ('1886\'da Witwatersrand\'da altının bulunması, Transvaal Cumhuriyeti\'nde hangi gelişmeye yol açmıştır?', 'Johannesburg\'un kurulması ve yabancı işçi akını', ['Boer devletinin dağılması', 'Zulu krallığının güçlenip Transvaal\'ın bir bölümünü ele geçirmesi', 'Kimberley\'nin terk edilmesi'], 'Altın hummasıyla Uitlander denen yabancılar Transvaal\'e doldu; bu durum Boer yönetimi ile İngiltere arasındaki gerilimi artırdı.'),
  ('İkinci Boer Savaşı\'nda (1899-1902) İngilizlerin Boer sivilleri toplayıp kamplara kapatmasının sonucu nedir?', 'Binlerce kadın ve çocuğun hastalık ve yetersizlikten ölmesi', ['Boerlerin teslim olmaması', 'Savaşın hemen bitip Boer devletlerinin bağımsızlığının tanınması ve ordunun terhisi', 'İngilizlerin zafer kazanamaması'], 'Kitchener\'in gerillaya karşı uyguladığı toplama kampları İngiltere\'de de tepkiyle karşılandı; yaşananlar Boer hafızasında kalıcı yara bıraktı.'),
  ('1902 Vereeniging Barışı sonrasında Boer cumhuriyetleri ne durumla karşılaşmıştır?', 'İngiliz egemenliğine girip özyönetim sözü almışlardır.', ['Bağımsızlıklarını koruyup Hollanda himayesine geri dönmüşlerdir ve vergi ödemişlerdir.', 'Almanya\'ya bağlanmışlardır.', 'Fransa\'ya devredilmişlerdir.'], 'Transvaal ve Orange Cumhuriyeti İngiliz sömürgeleri oldu; 1910\'da Güney Afrika Birliği kuruldu ve beyaz azınlık yönetimi sürdü.'),
  ('1910\'da kurulan Güney Afrika Birliği hangi dört sömürgenin birleşmesiyle oluşmuştur?', 'Cape, Natal, Transvaal ve Orange River', ['Cape, Zululand, Basutoland, Swaziland ve Natal sömürgelerinin', 'Rodezya, Natal, Cape ve Namibya', 'Mozambik, Cape, Natal ve Transvaal'], 'Birlik, İngiliz Dominyonu olarak kuruldu; siyahların siyasal haklarını sınırlayan yapı başından itibaren beyaz hâkimiyetine dayanıyordu.'),
  ('1912\'de kurulan ve sonradan Afrika Ulusal Kongresi adını alan örgütün ilk hedefi neydi?', 'Siyahların haklarını beyaz yönetime karşı yasal yollarla savunmak', ['Silahlı ayaklanma başlatmak', 'Güney Afrika\'yı Birleşik Krallık\'a katıp beyaz yönetimi pekiştirmek ve vergi toplamak', 'Sömürgeleri Almanya\'ya bağlamak'], 'Örgüt, 1913 Toprak Yasası gibi düzenlemelere dilekçe ve diplomasiyle itiraz ederek yola çıktı; sonradan kitlesel direnişe yöneldi.'),
  ('1913 Yerli Toprak Yasası\'nın Güney Afrika\'daki sonucu nedir?', 'Siyahların toprak edinebileceği alanı ülkenin küçük bir bölümüyle sınırlaması', ['Siyahlara ücretsiz toprak dağıtıp rezervleri tümüyle kaldırması ve çiftlikleri kamulaştırması', 'Beyazların toprak satın almasını yasaklaması', 'Rezerv sistemini kaldırması'], 'Yasa, siyah nüfusun çoğunluğuna ülkenin yaklaşık yüzde yedisinde toprak sahibi olma hakkı tanıdı; ayrımcılığın temel taşlarından biridir.'),
  ('Gandhi\'nin 1893-1914 arasında Güney Afrika\'da yaptığı çalışmalar sonucunda geliştirdiği mücadele yöntemi nedir?', 'Satyagraha', ['Gerilla savaşı ve sabotaj eylemleri', 'Parlamenter seçim kampanyası', 'Dilekçe yazma kampanyası'], 'Gandhi, Hint topluluğuna yönelik ayrımcı yasalara karşı pasif direniş yöntemini burada geliştirdi ve sonra Hindistan\'da kullandı.'),
  ('Kongo Serbest Devleti\'ndeki kauçuk toplama sisteminin en çok eleştirilen yönü aşağıdakilerden hangisidir?', 'Kotayı karşılamayanlara ağır şiddet uygulanması', ['Kauçuk üretimini tamamen yasaklaması ve kolonistleri sınır dışı etmesi', 'Yerli halka çok yüksek ücret ödeyerek ekonomik bağımlılık yaratması', 'Avrupalı işçilerin ağır koşullarda çalıştırılıp kıtadan kaçırılması'], 'Kota yerine getirilmezse el kesme, rehin alma gibi cezalar uygulandı; Morel ve Casement\'in kampanyaları sonunda devlet 1908\'de Belçika\'ya devredildi.'),
  ('Cecil Rhodes\'un \'Cape\'ten Kahire\'ye\' demiryolu projesinin dayandığı genişleme hayali neyi hedefliyordu?', 'Kıtayı kuzeyden güneye İngiliz hattıyla bağlamayı', ['Afrika\'yı Almanya ve Belçika ile eşit paylaşmayı', 'Kıtanın bağımsızlığını', 'Fransa ile ittifak kurmayı'], 'Rhodes Güney Afrika\'dan Mısır\'a kadar kesintisiz İngiliz toprakları görmek istedi; adını taşıyan Rodezya bu planın ürünüdür.'),
  ('1881\'de Sudan\'da Muhammed Ahmed\'in \'Mehdi\' olarak önderlik ettiği ayaklanmanın temel nedenlerinden biri nedir?', 'Ağır vergiler ve yolsuzluk', ['Sudan\'ın Etiyopya\'ya bağlanması', 'Kızıldeniz ticaretinin bitişi', 'Fransızların Sudan\'ı ele geçirmesi'], 'Mehdi hareketi hem dinî yenilenme çağrısı hem de dış yönetime tepki taşıyordu; 1885\'te Hartum\'u alıp General Gordon\'u öldürdü.'),
  ('1898 Omdurman Savaşı\'nda Kitchener komutasındaki İngiliz-Mısır ordusunun Mehdici güçleri yenmesinin nedeni nedir?', 'Makineli tüfek ve topçu üstünlüğü', ['Sayısal üstünlükleri', 'Mehdici güçlerin hiç silahı bulunmaması', 'Sudan halkının desteği'], 'Mehdici savaşçıların cesur hücumları makineli tüfek ateşi karşısında ağır kayıp verdi; Sudan İngiliz-Mısır ortak yönetimine girdi.'),
  ('Lord Lugard\'ın Nijerya\'da yaygınlaştırdığı \'dolaylı yönetim\' sistemi neye dayanır?', 'Yerel hükümdarlardan yararlanmaya', ['Yerel yöneticileri tamamen kaldırmaya', 'Kıtanın ortak parlamentoya bağlanmasına', 'Fransız hukukunun uygulanmasına'], 'İngiltere az sayıda görevliyle geniş toprakları yönetmek için mevcut hükümdarların otoritesinden yararlandı; Fransız asimilasyon anlayışından ayrılır.'),
  ('Süveyş Kanalı\'nın 1869\'da açılmasının Mısır tarihi açısından uzun vadeli sonucu aşağıdakilerden hangisidir?', 'Mısır\'ın borçlanıp işgale sürüklenmesi', ['Mısır\'ın bağımsız bir imparatorluğa dönüşmesi', 'Nil taşkınlarının sona ermesi', 'İngiltere\'nin Mısır\'dan çekilmesi'], 'Kanal ve altyapı yatırımları Hidiv\'i ağır borca soktu; İngiltere 1875\'te kanal hisselerini aldı ve 1882\'de Mısır\'ı işgal etti.'),
  ('1882\'de Mısır\'da Ahmed Urabi Paşa liderliğindeki ayaklanmanın hedefi neydi?', 'Yabancı müdahalesine karşı çıkmak', ['Osmanlı yönetimini devirip cumhuriyet kurmak', 'Sudan\'ı ele geçirmek', 'Hristiyanlığı yaymak'], 'Subaylar ve milliyetçiler Avrupa denetimine karşı çıktı; İngiltere\'nin İskenderiye\'yi bombalayıp Tel el-Kebir\'de Urabi\'yi yenmesi işgalin başlangıcı oldu.'),
  ('Kavalalı Mehmed Ali Paşa\'nın 1805\'ten sonra Mısır\'da yaptığı reformlardan biri aşağıdakilerden hangisidir?', 'Modern ordu, okul ve pamuk ekonomisi', ['Mısır\'ı bağımsız bir krallık ilan etmesi', 'Tarımı yasaklaması', 'Fransız yönetimini kabul etmesi'], 'Mehmed Ali, ordu, tersane, okul ve fabrikalar kurarak Mısır\'ı güçlü bir bölgesel devlete dönüştürmeyi amaçladı.'),
  ('Tunus\'un ve Fas\'ın 1956\'da Fransa\'dan bağımsızlığını kazanma biçimi hakkında aşağıdakilerden hangisi doğrudur?', 'Çok daha az çatışmayla, müzakereyle', ['Cezayir gibi uzun bir iç savaşla', 'Fransa\'nın askerî zaferiyle', 'Birleşmiş Milletler müdahalesiyle'], 'Tunus\'ta Burgiba, Fas\'ta Sultan V. Muhammed önderliğinde müzakere ve siyasi baskı yöntemi izlendi; yerleşimci sayısı Cezayir\'den azdı.'),
  ('1974 Portekiz Karanfil Devrimi\'nin Afrika sömürgeleri için sonucu nedir?', 'Sömürgelerin kısa sürede bağımsız olması', ['Portekiz\'in sömürgeleri genişletmesi', 'Sömürgelerin İspanya\'ya devri', 'Savaşların yeniden başlaması'], 'Salazar rejiminin ardından gelen yönetim sömürge savaşlarını bitirdi; bağımsızlıklar 1974-1975\'te gerçekleşti.'),
  ('1965\'te Güney Rodezya\'da Ian Smith yönetiminin Birleşik Krallık\'tan tek taraflı bağımsızlık ilan etmesinin amacı nedir?', 'Beyaz azınlık yönetimini sürdürmek', ['Siyah çoğunluk yönetimini kurmak', 'Güney Afrika Birliği\'ne katılıp onun parçası olmak', 'Portekiz\'e bağlanmak'], 'Smith rejimi çoğunluk yönetimine geçişi reddettiği için uluslararası yaptırımlara uğradı; 1980\'de Zimbabve çoğunluk yönetimiyle bağımsız oldu.'),
  ('1963\'te Addis Ababa\'da kurulan Afrika Birliği Örgütü\'nün (OAU) kabul ettiği temel ilkelerden biri aşağıdakilerden hangisidir?', 'Sömürgeden kalan sınırlara dokunmama', ['Afrika devletlerinin tek devlette birleşmesi', 'Sınırların yeniden çizilmesi', 'Silahlı müdahale hakkı'], 'Örgüt sınırlar yeniden çizilirse yeni çatışmalar çıkacağından sınırların dokunulmazlığını kabul etti; ancak bu etnik sorunları çözmedi.'),
  ('İdi Amin\'in 1971-1979 Uganda yönetimi için aşağıdakilerden hangisi söylenebilir?', 'Şiddet ve ekonomik çöküşle anılan bir diktatörlüktür.', ['Demokratik bir seçim dönemidir.', 'Sömürge yönetiminin devamıdır.', 'Sosyalist bir federasyondur.'], 'Amin 1972\'de Güney Asya kökenlileri sınır dışı etti; dış ticaret ve ekonomi çöktü, 1979\'da Tanzanya ordusu rejimi devirdi.'),
  ('1950 Nüfus Kaydı Yasası, Güney Afrikalıları hangi temelde sınıflandırmıştır?', 'Irksal gruplara', ['Gelir düzeyine göre vergi dilimlerine', 'Dil gruplarına göre resmî bölgelere', 'Eğitim durumuna göre sınıflara'], 'Kimlik belgesinde ırk kaydı yaşam alanı, meslek ve evlilik gibi birçok hakkı belirledi; bazı aileler aynı sınıflamayla bile bölündü.'),
  ('Güney Afrika\'da \'Bantustan\' (anavatan) politikasının hedefi neydi?', 'Siyahları ayrı \'bağımsız\' bölgelere bağlayarak Güney Afrika vatandaşlığından çıkarmak', ['Siyahlara tarım arazisi dağıtmak', 'Beyazları kırsala taşımak', 'Ülkeyi federasyona dönüştürmek'], 'Transkei gibi bölgelere sözde bağımsızlık verilerek siyahlar kendi ülkelerinde yabancı sayıldı; hiçbir bölge uluslararası olarak tanınmadı.'),
  ('1955 Kliptown\'da kabul edilen Özgürlük Şartı\'nın temel talebi nedir?', 'Güney Afrika\'nın hem siyahlara hem beyazlara ait olduğu ve herkes için eşit haklar', ['Beyaz yönetimin sürmesi', 'Siyahların ayrı devlet kurması', 'Ülkenin Britanya\'ya bağlanması'], 'Şart, ANC ve müttefiklerinin ortak programıydı; ırk ayrımı olmaksızın toprak, iş ve eğitimde eşit hak öngördü.'),
  ('21 Mart 1960 Sharpeville olayında yaşanan gelişme aşağıdakilerden hangisidir?', 'Polisin göstericilere ateş açması', ['Mandela\'nın serbest bırakılması', 'Ulusal Parti\'nin seçim zaferi', 'Zulu krallığının isyanı'], 'Olayda onlarca kişi öldü; hükümet olağanüstü hâl ilan edip ANC ve PAC\'ı yasakladı, dünya kamuoyu apartheid\'e tepki gösterdi.'),
  ('16 Haziran 1976\'da Soweto\'da başlayan öğrenci ayaklanmasının doğrudan tetikleyicisi nedir?', 'Afrikaans zorunlu öğretim dili kararı', ['Okul ücretlerinin artırılması', 'Mandela\'nın Robben Adası\'na gönderilmesi kararı', 'Yeni vergi yasası'], 'Öğrencilerin barışçıl yürüyüşü polis ateşiyle kanlı bir tepkiye dönüştü; olay uluslararası baskıyı ve rejime karşı direnişi büyüttü.'),
  ('11 Şubat 1990\'da Nelson Mandela\'nın serbest bırakılmasının hemen öncesindeki siyasi karar nedir?', 'De Klerk\'in ANC yasağını kaldırması', ['Mandela\'nın cumhurbaşkanı seçilmesi', 'ANC\'nin seçimi kazanması', 'Apartheid\'in askerî darbeyle yıkılması'], 'F. W. de Klerk, ANC ve PAC yasağını kaldırıp siyasi tutukluları serbest bırakarak müzakere sürecini başlattı.'),
  ('1993\'te Nobel Barış Ödülü\'nün Nelson Mandela ile birlikte kime verilmesi, süreç hakkında ne gösterir?', 'De Klerk\'e verilmesiyle', ['Başkan Reagan\'a verilmesiyle ABD\'nin başarısını', 'Desmond Tutu\'ya verilmesiyle kilisenin liderliğini', 'Steve Biko\'ya verilmesiyle direnişin sonucunu'], 'Ödül iki liderin, apartheid\'den çok ırklı demokrasiye geçişi sağlayan uzlaşmadaki rolüne verildi.'),
  ('1917 Meksika Anayasası\'nın dönemin diğer anayasalarından ayrılan yönü aşağıdakilerden hangisidir?', 'Toprak reformu ve işçi hakları getirmesi', ['Kralın yetkilerini artırıp meclisi kapatması', 'Mülkiyeti tamamen özelleştirmesi', 'Tek partili parlamento öngörmesi'], 'Anayasa, yeraltı kaynaklarını millî mülkiyet saydı, sekiz saatlik işgünü ve sendika hakkı tanıdı; dünyanın ilk sosyal anayasalarındandır.'),
  ('Başkan Lázaro Cárdenas\'ın 1938\'de Meksika\'da gerçekleştirdiği en dikkat çekici millileştirme hangisidir?', 'Petrol şirketlerinin millileştirilmesi', ['Demir yollarının özelleştirilmesi', 'Kilise topraklarının sahibinin değişmesi', 'Bankaların İspanya\'ya devri'], 'Yabancı petrol şirketlerine karşı işçilerle birlikte hareket eden Cárdenas, PEMEX\'i kurdu; olay Meksika\'da ulusal bağımsızlığın simgesi sayılır.'),
  ('Latin Amerika ülkelerinin 1930\'larda Büyük Buhran\'dan sonra benimsediği \'ithal ikameci sanayileşme\' politikası neyi amaçlıyordu?', 'İthalatı yerli üretimle ikame etmeyi', ['İhracatı tümüyle yasaklayıp dışa kapanmayı', 'Yabancı sermayeyi çoğaltmayı', 'Tarımı terk etmeyi'], 'Buhran ihracat gelirlerini çökertince ülkeler yüksek gümrükle yerli fabrikaları korudu; sanayileşti ancak dış rekabet gücü zayıf kaldı.'),
  ('Orta Amerika\'da \'muz cumhuriyetleri\' terimi hangi ekonomik yapıya işaret eder?', 'Tek ürüne ve yabancı şirketlere bağımlı ekonomilere', ['Çok çeşitli üretimi olan ve kendi kendine yeten sanayi ülkelerine', 'Yalnızca muzun yetiştiği adalara', 'Kooperatif temelli köylü devletlerine'], 'Honduras ve Guatemala gibi ülkelerde United Fruit gibi şirketler toprak ve limanlara hâkim oldu, hükümetleri etkiledi.'),
  ('Latin Amerika\'da 1960\'lar ve 1970\'lerde Şili, Arjantin ve Brezilya\'da yaşanan askerî darbelerin ortak özelliği nedir?', 'Seçilmiş hükümetleri devirmeleri', ['Krallık biçiminde yönetime dönmeleri ve kralların tahta çıkması', 'Birleşmiş Milletler yönetimine girişleri', 'Sendikaların yönetime gelişi'], 'Bu darbeler Soğuk Savaş ortamında sol hareketlere karşı yapıldı ve kayıplar, işkence gibi ağır ihlallerle anıldı.'),
  ('Orta Amerika\'da 1946-1990 arasında çeşitli ülkelerde yaşanan iç savaşların (Guatemala, El Salvador, Nikaragua) ortak toplumsal kökeni nedir?', 'Toprak ve gelir eşitsizliği ile otoriter yönetimler', ['Çok sayıda gümüş maden bulunması', 'Kuraklığın tek başına yarattığı kıtlık', 'Okullaşma oranının hızla artması ve sanayileşme'], 'Mülkiyetin az sayıda ailede toplanması, yerli köylülerin dışlanması ve dış müdahaleler iç savaşları besledi.'),
  ('1212 Las Navas de Tolosa Savaşı\'nda Muvahhidlerin Hristiyan krallıklar ittifakına yenilmesinin sonucu nedir?', 'Müslüman gücünün çöküşünün hızlanması', ['Muvahhid hanedanının Mısır\'ı fethi', 'Kastilya\'nın dağılması', 'Kuzey Afrika\'nın Avrupa\'ya bağlanması'], 'Yenilgiden sonra Muvahhid yönetimi zayıfladı ve Kurtuba ile Sevilla gibi kentler önümüzdeki yarım yüzyılda Hristiyan krallıkların eline geçti.'),
  ('Fes\'te 859\'da Fatıma el-Fihri tarafından kurulan Karaviyyin Kütüphanesi ve Medresesi neyle anılır?', 'En eski eğitim kurumlarından biri olmasıyla', ['Fas\'ın ilk matbaası olmasıyla', 'Muvahhid sarayı olmasıyla', 'Sahra\'daki ilk gözlemevi olmasıyla'], 'Bir kadın hayırsever tarafından yaptırılan kurum, yüzyıllar içinde İslam hukuku, felsefe ve bilim eğitimi veren bir üniversiteye dönüştü.'),
  ('Karayipler\'in yerli halkı Taíno\'dan, dünya dillerine geçen sözcüklere örnek hangisidir?', 'Hamak, kano ve kasırga', ['Piramit, mumya ve papirüs', 'Sultan, divan, kervansaray ve han sözcükleri', 'Mandala, yoga ve karma'], 'Taíno dili Avrupa dillerine hamaca, canoa, tabaco ve huracán gibi kelimeler kazandırdı.'),
  ('1954 Brown v. Board of Education kararında Yüksek Mahkeme hangi hükme varmıştır?', 'Okullarda ayrımın anayasaya aykırılığına', ['Yalnızca üniversitelerde ayrım yasağına', 'Siyahların askerlikten muaf olacağına', 'Ayrı ama eşit ilkesinin her alanda geçerli olduğuna'], 'Karar, \'ayrı ama eşit\' ilkesinin eğitimde eşitsizlik yarattığını belirterek Plessy kararının bu alandaki dayanağını ortadan kaldırdı.'),
  ('1964 Sivil Haklar Yasası hangi alanlarda ayrımcılığı yasaklamıştır?', 'Kamusal yerlerde ve işte ayrımcılığı', ['Yalnızca askerî okullarda ve kışlalarda ayrımcılığı', 'Yalnızca konutta ayrımcılığı', 'Yalnızca oy kullanmada ayrımcılığı'], 'Yasa, restoran, otel gibi kamu işletmelerinde ayrımı yasakladı ve işyerlerinde eşit istihdam ilkesini getirdi.'),
  ('1965 Oy Hakları Yasası\'nın çıkarılmasında Alabama\'daki Selma yürüyüşü hangi rolü oynamıştır?', 'Oy engellerine tepki oluşturmuştur.', ['Yasayı engellemiştir.', 'Seçimlerin süresiz ertelenmesini sağlamıştır.', 'Ayrımcı yasaların onaylanmasını sağlamıştır.'], 'Yürüyüşçülere uygulanan şiddet ulusal tepki doğurdu; yasa okuma-yazma testi gibi oy engellerini kaldırdı.'),
  ('Yaklaşık 1910-1970 arasında yaşanan \'Büyük Göç\'te milyonlarca Afrikalı Amerikalı hangi yönde yer değiştirmiştir?', 'Güney\'den Kuzey ve Batı kentlerine', ['Kuzey eyaletlerinden Güney\'e ve Karayipler\'e', 'Batı\'dan Afrika\'ya', 'Doğu\'dan Kanada\'ya'], 'İş imkânları ve Jim Crow yasalarından kaçış nedeniyle Chicago, Detroit ve New York gibi kentlerin siyah nüfusu hızla arttı.'),
  ('1831\'de Virginia\'da Nat Turner önderliğindeki köle isyanının Güney eyaletlerine etkisi nedir?', 'Köle yasalarının sertleşmesi', ['Köleliğin bütün Güney\'de kaldırılması', 'Kuzey\'in Güney\'e katılması', 'Kölelerin silah taşıma hakkı kazanması'], 'İsyan bastırıldıktan sonra Güney yönetimleri köle ayaklanmalarından korkarak eğitimi ve toplanmayı yasakladı.'),
  ('Frederick Douglass\'ın kölelik karşıtı harekette öne çıkmasının başlıca nedeni nedir?', 'Kaçak köle olarak tanıklık etmesi', ['Güney\'in orduda komutan olması', 'Güney\'in bir eyaletinde başkan seçilmesi', 'Mahkeme başkanlığı yapması'], 'Douglass özgürlüğüne kavuştuktan sonra yazdığı otobiyografi ve konuşmalarla dönemin en etkili kölelik karşıtı sesi oldu.'),
  ('Brigham Young önderliğindeki Mormonların 1847\'de Utah\'taki Büyük Tuz Gölü bölgesine göç etmesinin nedeni nedir?', 'Dinî baskıdan kurtulmak', ['Altın aramak', 'Kızılderililerle savaşmak', 'Kaliforniya\'ya altın aramaya gitmek'], 'Joseph Smith\'in öldürülmesinden sonra Mormonlar Illinois\'den ayrıldı ve henüz ABD sınırları dışında olan bölgede yerleşti.'),
  ('1830\'larda ABD\'de \'İkinci Büyük Uyanış\' hareketi hangi toplumsal reformları desteklemiştir?', 'Kölelik karşıtlığı ve eğitim reformunu', ['Köleliğin güçlenmesini', 'Kilise ile devletin birleşmesini', 'Yerlilerin sürülmesini'], 'Dinî coşku, birçok kişiyi toplumsal ahlak ve reform projelerine yöneltti; kadın hakları ve kölelik karşıtlığı bu ortamda gelişti.'),
  ('Alamo Savaşı\'nda 1836\'da Meksika ordusunun Texaslı savunmacıları yenmesinin Texas devrimi üzerindeki etkisi nedir?', 'Direnişi kamçılaması', ['Texas devriminin birkaç gün içinde sona ermesi', 'Meksika\'nın Texas\'ı ilhak etmesi', 'ABD\'nin devrimi desteklemeyi bırakması'], 'Savunmacıların ölümü Amerikan yerleşimcileri öfkelendirdi; San Jacinto\'da bu slogan Santa Anna\'nın yenilgisine katkı sağladı.'),
  ('Henry Clay\'in 1820 ve 1850 uzlaşmalarındaki rolü nedeniyle aldığı unvan nedir?', 'Büyük Uzlaştırıcı', ['Kuzey\'in Aslanı ve Birliğin Bekçisi', 'Kölelerin Dostu', 'Yeni Dünya Fatihi'], 'Clay, Kuzey-Güney gerilimini yatıştırmak için kölelik sorunlu eyalet katılımlarında uzlaşmalar düzenledi; ancak sorun uzlaşmayla kalıcı çözülmedi.'),
  ('Kuzey ve Güney\'in 1850\'lerde ekonomik yapısındaki fark, kölelik sorununu neden derinleştirmiştir?', 'Pamuk ve köle emeği ile sanayi farkı', ['Kuzey\'in yalnızca tarımdan kazanması', 'Güney\'in sanayide öncü olması', 'İki bölgenin aynı ekonomik yapıda olması'], 'Pamuk üretimi Güney\'in zenginliğinin temeliydi; kölelik kurumu hem ekonomik hem toplumsal güç ilişkilerini belirliyordu.'),
  ('Sahra\'nın Tuareg göçebelerinin kervan ticaretindeki rolü için aşağıdakilerden hangisi doğrudur?', 'Rehberlik ve haraçla ticareti denetlemişlerdir.', ['Kervanların taşıdığı mallar için Akdeniz kıyısında liman işletmişlerdir.', 'Altın ve tuz madenlerinin tamamını doğrudan kendi çalışanlarıyla işletmişlerdir.', 'Batı Afrika krallıklarının kervan vergilerini toplayıp Avrupa\'ya göndermişlerdir.'], 'Tuaregler Sahra\'yı iyi bilen göçebelerdi; kervan güzergâhlarında su ve güvenlik hizmeti verip karşılığında vergi alırdı.'),
  ('Batı Afrika\'da İslam\'ın yayılmasında en etkili yöntem aşağıdakilerden hangisidir?', 'Ticaret yoluyla', ['Haçlılara karşı yapılan büyük savaşlar yoluyla ve zorunlu iskân politikasıyla', 'Osmanlı ordularının Sahra\'yı sürekli işgal etmesiyle ve vergi toplamasıyla', 'Sömürge dönemindeki zorunlu dinî eğitim kurumlarıyla ve devlet destekli misyonla'], 'Sahra ötesi kervan ağları ve Müslüman tüccarlar İslam\'ı krallıkların saray çevrelerinde yayarak kalıcı bir etki bıraktı.'),
  ('Afrika\'da 19. yüzyılda Avrupalı misyonerlerin yarattığı en kalıcı toplumsal etki aşağıdakilerden hangisidir?', 'Eğitimli yeni bir seçkin yetişmesi', ['Yerli yöneticileri tümüyle ortadan kaldırıp hükümdarlık sistemini sona erdirmeleri', 'Afrika dillerini tamamen yasaklayıp yalnızca Latince eğitimi zorunlu kılmaları', 'Afrikalı halkın tamamını aynı yılda Hristiyanlığa geçirip kiliseleri kurmaları'], 'Misyon okulları okuma yazma ve yeni meslekler öğretti; milliyetçi hareketlerin birçok lideri bu okullardan yetişti.'),
  ('Sömürge dönemi Afrika ekonomisinde \'nakit ürün\' (cash crop) politikasının sonucu nedir?', 'Yerel gıda üretiminin azalması', ['Köylülerin tamamen sanayi işçisi olması ve tarımın bırakılması', 'Afrika ülkelerinin Avrupa\'dan daha fazla gıda ihraç etmesi ve kalkınması', 'Yerel hükümdarların tüm tarım arazilerini kamulaştırması ve ihracatı yasaklaması'], 'Kakao, pamuk ve fıstık gibi ürünlere yönelme dış fiyatlara bağlılığı artırdı ve yerel beslenme ürünlerinin üretimini azalttı.'),
  ('II. Dünya Savaşı\'nın Afrika siyasetine etkilerinden biri aşağıdakilerden hangisidir?', 'Bağımsızlık beklentilerinin artması', ['Tüm Afrikalıların Avrupa\'da kalıcı vatandaşlık alması', 'Sömürgeci devletlerin güçlenip yeni sömürgeler kurması', 'Afrika\'da hiçbir siyasal değişim yaşanmaması'], 'Avrupa\'nın zayıflaması ve savaşa katılan binlerce askerin eşitlik beklentisi, bağımsızlık hareketlerini besledi.'),
  ('Sömürge Afrika\'sında Fransız ve İngiliz yönetimleri arasında yerel yönetim anlayışı bakımından hangi karşılaştırma doğrudur?', 'İngiltere dolaylı, Fransa doğrudan yönetim', ['Her iki devlet de yerel hükümdarları kaldırıp yalnızca askerî yönetim kurmuştur.', 'İngiltere sömürgelerinde Fransızca eğitim vermiştir.', 'Fransa sömürgelerinde yerli hükümdarlara tüm yetkiyi devretmiştir.'], 'İngiliz yöntemi maliyet düşürmek için yerel yapıları kullanırken Fransız yöntemi merkezden atanan görevlilere ve Fransız kültürüne dayanıyordu.'),
  ('Afrika\'da 19. yüzyılın sonunda kıtayı baştan sona sömürgeleştirme hızına yol açan ekonomik etken aşağıdakilerden hangisidir?', 'Sanayi Devrimi\'nin ham madde ihtiyacı', ['Atlantik köle ticaretinin yeniden başlaması', 'Avrupa\'da nüfusun azalması', 'Altın standardının kalkması'], 'Fabrika üretimi kauçuk, pamuk, maden ve yeni pazarlar istiyordu; bu yarış Berlin Konferansı\'ndan sonra hızlandı.'),
  ('Afrika\'da sömürge yönetiminin getirdiği demiryolları genellikle neden kıyı limanlarına doğru uzanır?', 'İhracat limanına ham madde taşımak için', ['İç bölgeleri birbirine bağlamak için', 'Tarım ürünlerini yerel pazarlara dağıtmak için', 'Kıyıdaki nüfusu iç bölgeye taşımak için'], 'Hatlar sömürgeci ekonomi için kurulduğundan iç ticaretten çok maden ve tarım ürünlerini limana taşımaya göre planlandı.'),
  ('Afrika\'da sömürge sınırlarının etnik gruplara göre çizilmemesinin bağımsızlık sonrası yarattığı sorun nedir?', 'Halkların bölünüp birleşmesiyle çatışma', ['Hiç sınır sorununun yaşanmaması', 'Bütün ülkelerin etnik bakımdan tek tip olması', 'Devletlerin kıyılarının kaybolması'], 'Berlin sonrası çizilen düz sınırlar yerel kimlikleri dikkate almadı; bu durum bağımsızlık dönemi iç savaşlarına zemin hazırladı.'),
  ('Afrika\'da Haile Selassie\'nin 1963\'te Addis Ababa\'da OAU\'nun kurulmasındaki rolü nedir?', 'Kuruluşa ev sahipliği ve öncülük etmesi', ['Örgütün ilk başkanı olarak Mısır\'ı yönetmesi', 'Örgütü Etiyopya\'nın sömürgesi hâline getirmesi', 'Örgütün Avrupa merkezli olmasını sağlaması'], 'Addis Ababa örgütün merkezi oldu; Etiyopya sömürgeleşmemiş tarihi nedeniyle kıtada itibar sahibiydi.'),
  ('Afrika\'da tarihî yazılı kaynakların azlığı nedeniyle tarih araştırmalarında başvurulan yöntem hangisidir?', 'Sözlü gelenek, dil ve arkeoloji', ['Yalnızca Avrupalı gezginlerin notlarına dayanmak', 'Yalnızca sömürge arşivlerini okumak', 'Tarih araştırmayı bırakmak'], 'Sözlü tarih (griotlar), dillerin karşılaştırılması ve kazılar yazılı kaynakların eksikliğini tamamlar; Avrupa merkezli bakış tek başına yeterli değildir.'),
  ('Amerika kıtasına ilk insan topluluklarının ulaşma yolu için genel kabul gören açıklama hangisidir?', 'Asya\'dan Bering kara köprüsü üzerinden', ['Atlantik\'te yelkenli gemilerle Avrupa\'dan', 'Pasifik\'te Çin\'den gelen tüccar filolarıyla', 'Afrika kıyılarından deniz akıntılarıyla'], 'Son buzul çağında deniz seviyesi düşünce Sibirya ile Alaska arasındaki kara kuşağı göçe imkân verdi; göçün kesin zamanı hâlâ tartışmalıdır.'),
  ('1680\'de New Mexico\'da Pueblo halklarının önderi Popé liderliğinde başlayan ayaklanmanın sonucu nedir?', 'İspanyolların bölgeden geçici olarak sürülmesi', ['İspanyolların Pueblo\'ları kalıcı olarak yenmesi', 'Pueblo\'ların ABD\'ye katılması', 'Santa Fe\'nin yıkılıp bir daha kurulmaması'], 'İspanyolların din baskısına tepki duyan Pueblo halkları Santa Fe\'yi aldı; İspanyollar 1692-1696\'da yeniden döndü.'),
  ('Aztek ve Maya kentlerinde rastlanan \'tzompantli\' (kafatası rafı) hangi dinî ve siyasi işleve sahipti?', 'Gücü ve gözdağını sergilemek', ['Ölülerin ruhlarını anmak için mezar alanı oluşturmak', 'Tarım hasadını ve bereketi kutlamak', 'Tüccarlara pazar yeri hazırlamak'], 'Savaş esirlerinin kurban edilmesi hem dinî görev hem de komşulara gözdağıydı; İspanyollar bu uygulamayı büyük bir dehşetle anlatmıştır.'),
  ('Machu Picchu\'nun 15. yüzyılda Pachacuti için inşa edildiği ileri sürülen kullanım amacı aşağıdakilerden hangisidir?', 'Kraliyet malikânesi ve dinî merkez', ['Büyük bir askerî karargâh', 'Pasifik\'teki ticaret limanı', 'Madencilik şehri'], 'Yapının teraslar, tapınaklar ve konutlar içermesi, hükümdar için yaylak ve tören mekânı olduğunu düşündürür.'),
  ('Aşağıdaki olayları eskiden yeniye doğru dizen sıra hangisidir?', 'Pizarro\'nun Cajamarca baskını, Boston Çay Partisi, Ayacucho Savaşı, Fashoda Krizi', ['Boston Çay Partisi, Pizarro\'nun Cajamarca baskını, Fashoda Krizi, Ayacucho Savaşı', 'Ayacucho Savaşı, Fashoda Krizi, Pizarro\'nun Cajamarca baskını, Boston Çay Partisi', 'Fashoda Krizi, Ayacucho Savaşı, Boston Çay Partisi, Pizarro\'nun Cajamarca baskını'], 'Cajamarca 1532, Boston Çay Partisi 1773, Ayacucho 1824, Fashoda 1898\'dir.'),
  ('Bir Boer çiftçisi 1830\'larda şöyle yazmıştır: \'İngiliz yasaları bizi köylerimizden ve emeğimizden mahrum bırakıyor; özgür bir ülke arıyoruz.\' Bu ifade hangi olayla ilişkilidir?', 'Büyük Trek', ['Mfecane', 'Kan Nehri Savaşı', 'Jameson Baskını'], 'İfade, Cape\'te İngiliz yönetimine ve köleliğin kaldırılmasına tepki gösteren Boerlerin kuzeye göçünü anlatır.'),
  ('Bir tarihçi şöyle yazıyor: \'Yerliler artık Avrupalı hastalıklarına karşı savunmasız olduğundan, fatihler az sayıda askerle büyük imparatorlukları yıkabildi.\' Bu görüş hangi olguya dayanır?', 'Salgınlardan kitlesel ölümler', ['Yerlilerin hiç savaşmaması', 'Avrupalıların çok büyük ordular kurup sefere çıkması', 'Yerli silahlarının demirden olmaması'], 'Çiçek hastalığı gibi salgınlar yerli nüfusu azaltıp yönetim ve ordu yapısını zayıflattı; fetihte tek etken değil ama önemli bir etkendi.'),
  ('\'Temsil yoksa vergi yok\' sloganının dayandığı düşünce, hangi anayasal ilkeye benzer?', 'Rıza olmadan vergi konulamaması ilkesine', ['Kralın ilahi hak yönetimine', 'Merkezî planlı kalkınma ekonomisine', 'Köleliğin korunmasına'], 'Koloniler, İngiliz Parlamentosu\'nda temsilcileri bulunmadığı için vergiyi meşru saymadı; bu İngiltere\'deki Haklar Bildirgesi geleneğine dayanıyordu.'),
  ('1803\'te Vertières Savaşı\'nda Haitililerin Fransız ordusunu yenmesi hangi sonucu doğurmuştur?', 'Haiti\'nin bağımsızlık ilan etmesi', ['Fransa\'nın Haiti\'yi tekrar fethi', 'Haiti\'nin İngiltere\'ye bağlı bir koloni olması', 'Haiti\'de kölelik kurumunun korunması'], 'Dessalines komutasındaki ordu Fransızları adadan çıkardı ve Haiti, köleliğin kaldırıldığı ilk bağımsız Latin Amerika devleti oldu.'),
  ('1919 Mısır Devrimi\'ni tetikleyen olay aşağıdakilerden hangisidir?', 'Saad Zaglul\'un sürgüne gönderilmesi', ['Süveyş Kanalı\'nın açılması', 'Urabi Paşa\'nın idam edilmesi olayı', 'Memlüklerin Kahire\'yi alması'], 'Zaglul\'un Paris Barış Konferansı\'na gitmek istemesi engellenip sürülünce Mısır\'da kitlesel gösteriler başladı; 1922\'de kısmi bağımsızlık tanındı.'),
  ('ABD Anayasası\'nın 15. Maddesi (1870) neyi hedeflemiştir?', 'Irk nedeniyle oy engellenmemesini', ['Kadınlara tam oy hakkı tanımayı amaçlamıştır', 'Kölelik yasağını', 'Gelir vergisini'], 'Madde, eski kölelerin erkeklerine oy hakkı sağlamayı amaçladı; ancak Güney\'de okuma testleri ve baskıyla sonraki yüzyılda fiilen engellendi.'),
  ('Bugünkü Nijerya\'da Oyo İmparatorluğu\'nun komşuları karşısındaki askerî üstünlüğünü sağlayan temel unsur nedir?', 'Süvari birlikleri', ['Deniz donanması ve kıyı kaleleri', 'Fildişi mızraklı yaya ordusu ve zırhlı gemiler', 'Dağ kalelerinde konuşlu ağır topçu birlikleri'], 'Savan kuşağında yer alan Oyo, kuzeyden aldığı atlarla güçlü bir süvari ordusu kurdu ve 18. yüzyıla dek bölgenin başlıca gücü oldu.'),
  ('Svahili kıyısındaki liman kentlerinin (Kilwa, Lamu, Mombasa) ticaret mallarını en iyi anlatan seçenek hangisidir?', 'Fildişi, altın, köleler ve baharat', ['Yalnızca buğday ve pirinç', 'Çin ipeği ve Roma şarabı', 'Petrol ve doğal gaz'], 'Hint Okyanusu ticaretinde Afrika içlerinden gelen altın ve fildişi, Arabistan, Hindistan ve Çin\'den gelen mallarla değiştirilirdi.'),
  ('1754\'te Benjamin Franklin\'in \'Birleş ya da Öl\' karikatürüyle desteklediği Albany Planı\'nın amacı neydi?', 'Kolonileri ortak yönetimde birleştirmek', ['Kolonileri İngiltere\'den hemen ve silahla ayırmak', 'Çay ticaretini yasaklamak', 'Köleliği kaldırmak'], 'Plan kabul görmedi ama kolonilerin ortak hareket etmesi gerektiği fikrinin erken örneği oldu.'),
  ('Jamestown\'da 1609-1610 kışında yaşanan \'Açlık Dönemi\' koloniyi nasıl etkilemiştir?', 'Nüfusun büyük bölümünü kaybettirmiştir.', ['Kolonistleri zenginleştirmiştir.', 'Yerlilerle kalıcı bir barış anlaşması yapılmasını sağlamıştır.', 'Kolonileri İngiltere\'ye bağlamıştır.'], 'Kış boyunca yiyecek bittiği için yaklaşık yüz kişi kalacak kadar nüfus azaldı; yeni gelen vali ve erzak koloniyi kurtardı.'),
  ('1775\'te Bunker Hill Savaşı\'nın Amerikan Devrimi\'ndeki önemi nedir?', 'Kolonilerin acemi güçlerinin İngiliz ordusuna ağır kayıp verdirebileceğini göstermesi', ['İngiltere\'nin kesin zaferi', 'Fransa\'nın savaşa girmesi', 'Washington\'ın teslim olması'], 'Britanya kente girse de büyük kayıp verdi; milis kuvvetlerinin cesareti kolonilerin savaşı sürdürme kararlılığını güçlendirdi.'),
  ('Noel gecesi 1776\'da Washington\'ın Delaware Nehri\'ni geçerek Trenton\'da Hessen askerlerini şaşırtması neyi sağlamıştır?', 'Orduya moral ve güven kazandırmayı', ['Savaşın hemen bitmesini', 'İngiltere\'nin barış istemesini', 'Fransa\'nın hemen ittifak ve yardım anlaşması yapmasını'], 'Zafer, ordunun dağılma noktasına geldiği bir dönemde moral ve gönüllü akışını artırdı.'),
  ('Eylül 1862\'de Maryland\'deki Antietam Muharebesi, tek günde verilen kayıplar bakımından nasıl anılır?', 'Tek günlük en kanlı savaş olarak', ['En az kayıplı muharebe olarak', 'İç Savaş\'ın son ve en az kayıplı muharebesi olarak', 'Fransa\'nın katıldığı bir savaş olarak'], 'Kuzey ve Güney yaklaşık yirmi iki bin kayıp verdi; savaş Lee\'nin Kuzey\'e ilerleyişini durdurdu ve Özgürlük Bildirgesi\'ne zemin hazırladı.'),
  ('1877 Uzlaşması\'nın ardından federal birliklerin Güney\'den çekilmesi hangi sonuca yol açmıştır?', 'Yeniden Yapılanma\'nın sona ermesi', ['Yeni bir iç savaşın başlaması', 'Siyahların siyasi gücünün artması', 'Konfederasyon\'un kesin olarak yeniden kurulması'], 'Kongre\'deki seçim anlaşmazlığı çözülürken askerler çekildi; Güney\'de Jim Crow yasalarının ve siyahlara yönelik şiddetin önü açıldı.'),
  ('Louisiana\'nın 1803\'te ABD\'ye geçişinden sonra New Orleans\'ın önemi neden büyüktür?', 'Mississippi ağzındaki liman olması', ['Altın madenleri bulundurması', 'Savunma amaçlı büyük bir kale olması ve donanma üssü', 'Kuzey kutbuna yakın olması'], 'Batı çiftçilerinin ürünleri nehirle New Orleans\'a iner ve oradan denize açılırdı; şehre sahip olmak ABD ekonomisi için hayatiydi.'),
  ('1815\'te New Orleans Savaşı\'nın ABD için sembolik önemi nedir?', 'Jackson\'ı ulusal kahraman yapması', ['Fransa\'nın zaferi olması', 'Kanada\'nın alınması', 'Louisiana\'nın İngiltere\'ye devredilmesi'], 'Savaş aslında Gent Antlaşması\'ndan sonra yapıldı, ama kazanılan zafer Jackson\'ın şöhretini yükseltti.'),
  ('Maya hükümdarlarının ve soylularının kendi kanlarını sunmaları (kan alma) ritüeli neyi amaçlıyordu?', 'Tanrılarla bağ kurup düzeni sürdürmeyi', ['Savaşı kazanma sihrini bozmayı', 'Yeni bir yazı sistemi bulmayı', 'Vergi toplamayı'], 'Kan, tanrılara en değerli sunu sayılırdı; hükümdar bu ritüelle gök ve yeraltı dünyası arasındaki ilişkiyi sürdürdüğüne inanılırdı.'),
  ('1814\'te İngilizlerin Washington\'ı işgal edip Beyaz Saray\'ı yakması hangi savaşın içinde yer alır?', '1812 Savaşı', ['Meksika-Amerikan Savaşı', 'Amerikan Bağımsızlık Savaşı', 'İç Savaş'], 'İngiliz birlikleri başkentteki resmî binaları yaktı; Baltimore\'daki Fort McHenry\'nin bombardımanı da ABD\'nin ulusal marşının sözlerine ilham verdi.'),
  ('Meksika\'da Antonio López de Santa Anna\'nın tarihteki yeri için hangisi doğrudur?', 'Birçok kez başa gelen, toprak kaybettiren general', ['Meksika\'nın ilk imparatoru', 'Devrimin köylü önderi ve toprak reformu savunucusu', 'Fransız Meksikası\'nın hükümdarı'], 'Santa Anna, birçok kez cumhurbaşkanı oldu; Texas\'ın kaybı ve 1848 sonrası toprak kayıplarıyla anılır.'),
  ('Lunda ve Luba krallıklarının Orta Afrika\'da gelişmesinde önemli rol oynayan faaliyet hangisidir?', 'Bakır ve tuz ticareti', ['Okyanus balıkçılığı ve gemi yapımı', 'Şeker üretimi', 'Buğday ihracatı'], 'Güney Kongo\'daki bakır kuşağı ve uzak mesafe ticaret ağı, bu krallıkların zenginleşmesini sağladı.'),
  ('Kwame Nkrumah\'ın 1957 sonrası Pan-Afrikan vizyonunun temel ilkesi nedir?', 'Afrika\'nın siyasi ve ekonomik birliği', ['Avrupa\'ya bağlılık', 'Afrika\'nın bölünmesi', 'Sömürge yönetimine yeniden dönüş'], 'Nkrumah, \'Önce siyasi krallığı arayın\' diyerek kıtanın birleşik bir Afrika Devletleri Birliği altında bağımsız olmasını savundu.'),
  ('Güney Afrika\'da 1960\'ta Albert Luthuli\'nin Nobel Barış Ödülü\'nü almasının önemi nedir?', 'Şiddetsiz direnişin tanınması', ['Rejimin ödüllendirilmesi ve yaptırımların kalkması', 'Güney Afrika\'nın BM üyeliği', 'Mandela\'nın serbest bırakılması'], 'Luthuli, ANC başkanıydı ve ödülü alan ilk Afrikalıdır; ödül apartheid muhalefetine uluslararası destek getirdi.'),
  ('1864\'te Navajo halkının Arizona\'dan New Mexico\'daki Bosque Redondo\'ya yürütülmesi hangi adla anılır?', 'Uzun Yürüyüş (Long Walk)', ['Gözyaşı Yolu (Cherokee sürgünü yürüyüşü)', 'Kızıl Bulut Yürüyüşü', 'Mayıs Yürüyüşü'], 'Kit Carson önderliğindeki ordu, Navajo ekinlerini ve sürülerini yok ederek binlerce kişiyi rezervasyona yürüttü; yürüyüşte ve sonrasında çok kayıp yaşandı.'),
  ('1864\'te Colorado\'da bir milis kuvvetinin barış bayrağı çekmiş Cheyenne ve Arapaho köyüne saldırdığı olay hangisidir?', 'Sand Creek Katliamı', ['Wounded Knee Katliamı', 'Little Bighorn Savaşı', 'Alamo Savaşı'], 'Saldırıda çoğu kadın ve çocuk olan yüzlerce yerli öldürüldü; olay Kongre soruşturmasına konu oldu ve yerli-federal ilişkilerde büyük kırılma yarattı.'),
  ('1798 Yabancılar ve Fitne Yasaları (Alien and Sedition Acts) ABD\'de neye yol açmıştır?', 'İfade özgürlüğü tartışması', ['Köleliğin kaldırılmasına', 'Kızılderili sürgününe', 'Çay vergisinin kaldırılıp ticaretin serbest bırakılmasına'], 'Federalistlerin çıkardığı yasalar muhalif gazetecileri cezalandırdı; Jefferson ve Madison eyaletlerin yasaları reddedebileceğini savunan kararlar kaleme aldı.'),
  ('1845\'te Texas\'ın ABD\'ye katılması, Meksika ile ilişkileri nasıl etkilemiştir?', 'Savaşa zemin hazırlamıştır', ['Meksika\'yla ittifak kurulmasına yol açmıştır', 'Meksika\'nın Texas\'ı silahla geri almasını sağlamıştır', 'Kaliforniya\'nın bağımsızlığına yol açmıştır'], 'Meksika, Texas\'ın bağımsızlığını hiç tanımamıştı; ilhak sınır anlaşmazlığını ve savaşı yakınlaştırdı.'),
  ('David Livingstone\'un 1855\'te Zambezi Nehri üzerinde Avrupalılara tanıttığı doğal oluşuma verdiği ad nedir?', 'Victoria Şelalesi', ['Niagara Şelalesi\'nin Afrikalı benzeri', 'Büyük Rift', 'Kilimanjaro'], 'Livingstone, yerli adı \'gürleyen duman\' olan şelaleye kraliçenin adını verdi; sonraki Afrika keşifleri için halk ilgisini çoğalttı.'),
  ('Kongo Krallığı\'nın başkenti Mbanza Kongo\'nun Portekizliler tarafından verilen adı nedir?', 'São Salvador', ['Luanda', 'Lourenço Marques', 'Benguela'], 'Hükümdarın Hristiyanlığı kabulünden sonra başkent kiliselerle donatıldı ve Portekizce \'Kurtarıcı Aziz\' anlamına gelen adla anıldı.'),
  ('Mali\'nin kurucusu Sundiata\'nın hayatını anlatan ve sözlü gelenekle aktarılan destanın Mali kimliği için önemi nedir?', 'Ortak tarih bilinci oluşturması', ['Yazılı hukuk metni olması', 'Dinî kutsal kitap olarak okunması', 'Sadece çocuk masalı olması'], 'Destan, griotlarca yüzyıllardır okunur; devletin kuruluşunu ve hükümdarın kahramanlığını anlatarak toplumsal hafızayı yaşatır.'),
  ('Sahra\'nın güneyinde kervanların uğrak noktası olan Tegazza ve Taoudenni maden bölgeleri en çok hangi ürünle bilinir?', 'Kaya tuzu', ['Altın ve gümüş', 'Fildişi', 'Demir'], 'Bu tuz yataklarından çıkarılan levhalar develerle güneye taşındı; tuz tropik halk için hayatî öneme sahipti.'),
  ('Sierra Leone\'de eski kölelerin soyundan gelen halkın oluşturduğu ve İngilizce temelli bir dil konuşan topluluğa ne ad verilir?', 'Kriolar', ['Svahililer', 'Mandingolar', 'Bantular'], 'Freetown\'a yerleşen azat edilmiş köleler ve soyundan gelenler Krio dilini geliştirdi; topluluk ülkenin siyasi ve kültürel hayatında önemli yer tuttu.'),
];
